select ac_cargar_unidad($ac${"slug":"ciencia-1","rama":"ciencia","orden":1,"nivel":1,"titulo_es":"Cómo sabemos lo que sabemos","bajada_es":"Observar, preguntar, probar y corregir: el método que permite saber que el clima cambia, que un remedio funciona o que un río está contaminado.","objetivos_es":["Distinguir observaciones de inferencias y formular preguntas investigables","Diseñar un experimento justo con variables y grupo de control","Reconocer errores de medición y la importancia del tamaño de la muestra","Diferenciar correlación de causalidad","Explicar cómo la ciencia construye consenso y se corrige"],"repasa":["tronco-2"],"requiere_tronco":1,"fuentes":["consenso-cook-2016","ipcc-ar6-syr","nasa-evidencia","chequeado","ncse-ozono","naaee-guidelines"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"ciencia-1.s1","orden":1,"tipo":"leccion","titulo_es":"Observar y preguntar","bajada_es":"La diferencia entre lo que ves y lo que suponés, y cómo convertir una curiosidad en una pregunta que se pueda investigar.","minutos":11,"pasos":[{"slug":"ciencia-1.s1.p1","orden":1,"grupo":"ciencia-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Observación e inferencia","cuerpo":["Una observación es lo que se percibe directamente con los sentidos o con instrumentos: \"el agua del arroyo es marrón\", \"el termómetro marca 32 °C\", \"hay 12 horneros en la plaza\". Una inferencia es una interpretación de lo observado: \"el arroyo está contaminado\", \"hace más calor que antes\", \"a los horneros les gusta esta plaza\".","Las inferencias pueden ser correctas o no. El primer paso del pensamiento científico es separar lo que se ve de lo que se supone."]},"solucion":{}},{"slug":"ciencia-1.s1.p2","orden":2,"grupo":"ciencia-1.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una observación o una inferencia?","grupos":[{"id":"g1","nombre":"Observación"},{"id":"g2","nombre":"Inferencia"}],"items":[{"id":"i1","texto":"El agua del arroyo es marrón"},{"id":"i2","texto":"El arroyo está contaminado por una fábrica"},{"id":"i3","texto":"El termómetro marca 32 °C"},{"id":"i4","texto":"Este verano es más caluroso por el cambio climático"},{"id":"i5","texto":"Conté 12 horneros en la plaza"},{"id":"i6","texto":"A los horneros les gusta esta plaza"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El agua marrón puede ser sedimento de una lluvia, no contaminación. Separar lo que se ve de lo que se supone evita conclusiones apuradas."}},{"slug":"ciencia-1.s1.p3","orden":3,"grupo":"ciencia-1.s1.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"\"El agua del arroyo está contaminada\" es una observación directa.","razones":[{"id":"r1","texto":"Porque es una interpretación que hay que comprobar midiendo"},{"id":"r2","texto":"Porque la contaminación siempre se ve a simple vista"},{"id":"r3","texto":"Porque todo lo que se dice sobre el agua es una observación"}]},"solucion":{"valor":false,"explicacion":"Es una inferencia: se ve el color, el olor o la espuma, pero para saber si está contaminada hay que medir. El agua marrón puede ser solo barro.","clave":["r1"]}},{"slug":"ciencia-1.s1.p4","orden":4,"grupo":"ciencia-1.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Preguntas que se pueden investigar","cuerpo":["No toda pregunta se puede responder con ciencia. \"¿Es lindo el río?\" depende de gustos. \"¿Cuánto oxígeno disuelto tiene el río antes y después de la fábrica?\" se puede medir.","Una buena pregunta investigable es concreta, se puede responder con datos y dice qué se va a comparar o medir."]},"solucion":{}},{"slug":"ciencia-1.s1.p5","orden":5,"grupo":"ciencia-1.s1.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta pregunta se puede investigar con datos o no?","grupos":[{"id":"g1","nombre":"Investigable"},{"id":"g2","nombre":"No investigable así"}],"items":[{"id":"i1","texto":"¿Crecen más los porotos con compost que sin compost?"},{"id":"i2","texto":"¿Es más lindo el ceibo que el jacarandá?"},{"id":"i3","texto":"¿Cuántas aves visitan la plaza a la mañana y a la tarde?"},{"id":"i4","texto":"¿Deberían gustarle a todos las plantas nativas?"},{"id":"i5","texto":"¿Baja la temperatura bajo los árboles de la vereda?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Las preguntas de gusto u opinión no se resuelven midiendo. Las que comparan o cuantifican, sí."}},{"slug":"ciencia-1.s1.p6","orden":6,"grupo":"ciencia-1.s1.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la pregunta más investigable?","opciones":[{"id":"o1","texto":"¿Baja el consumo si se apagan las luces en los recreos?"},{"id":"o2","texto":"¿Es importante que todos cuidemos la energía en la escuela?"},{"id":"o3","texto":"¿Qué opina la gente sobre la energía solar en general?"},{"id":"o4","texto":"¿Está mal gastar energía durante los recreos de la escuela?"}]},"solucion":{"clave":["o1"],"explicacion":"Concreta, medible y con una comparación clara: antes y después de apagar las luces.","por_opcion":{"o3":"Se puede investigar con encuestas, pero así planteada es vaga: ¿qué gente?, ¿qué opinión?"}}},{"slug":"ciencia-1.s1.p7","orden":7,"grupo":"ciencia-1.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Del problema a la pregunta","cuerpo":["Muchas veces se parte de un problema general —\"el arroyo está feo\"— y hay que convertirlo en preguntas concretas: ¿qué parámetros del agua cambian?, ¿dónde?, ¿cuándo?, ¿cuánto? Cada pregunta concreta lleva a una medición."]},"solucion":{}},{"slug":"ciencia-1.s1.p8","orden":8,"grupo":"ciencia-1.s1.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para pasar de una curiosidad a una pregunta investigable.","items":[{"id":"i1","texto":"Notar algo que llama la atención"},{"id":"i2","texto":"Describir lo observado sin interpretar"},{"id":"i3","texto":"Pensar posibles explicaciones"},{"id":"i4","texto":"Formular una pregunta concreta que se pueda medir"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"De la curiosidad a la pregunta: observar, describir, imaginar y precisar."}},{"slug":"ciencia-1.s1.p9","orden":9,"grupo":"ciencia-1.s1.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una pregunta sea buena para investigar? Marcá todo.","opciones":[{"id":"o1","texto":"Que sea concreta"},{"id":"o2","texto":"Que se pueda responder con datos"},{"id":"o3","texto":"Que diga qué se va a comparar o medir"},{"id":"o4","texto":"Que se pueda investigar con los recursos disponibles"},{"id":"o5","texto":"Que la respuesta ya se sepa de antemano"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Si ya se sabe la respuesta, no hay investigación: hay confirmación de prejuicios."}},{"slug":"ciencia-1.s1.p10","orden":10,"grupo":"ciencia-1.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada observación con una inferencia posible.","izquierda":[{"id":"a1","texto":"Hay espuma blanca en el arroyo"},{"id":"a2","texto":"Los árboles de una cuadra tienen hojas amarillas en verano"},{"id":"a3","texto":"No se ven lombrices en el cantero"},{"id":"a4","texto":"El medidor de luz gira rápido a la noche"}],"derecha":[{"id":"b1","texto":"Puede haber detergentes en el agua"},{"id":"b2","texto":"Puede faltarles agua o nutrientes"},{"id":"b3","texto":"El suelo puede estar compactado o pobre"},{"id":"b4","texto":"Puede haber un aparato encendido"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada inferencia es una posibilidad que hay que comprobar, no una conclusión."}},{"slug":"ciencia-1.s1.p11","orden":11,"grupo":"ciencia-1.s1.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe de un grupo escolar y marcá lo que es inferencia presentada como si fuera un hecho.","segmentos":[{"id":"s1","texto":"Medimos 4 mg/L de oxígeno disuelto aguas abajo del puente."},{"id":"s2","texto":"La fábrica de al lado es la culpable de la contaminación."},{"id":"s3","texto":"Aguas arriba medimos 7 mg/L."},{"id":"s4","texto":"Todos los peces del arroyo se murieron."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los datos son el piso. Las interpretaciones hay que presentarlas como hipótesis hasta probarlas.","por_opcion":{"s2":"Es una inferencia: hay que comparar aguas arriba y abajo de la descarga y descartar otras causas.","s4":"No se observó todo el arroyo: es una generalización que no surge de las mediciones."}}},{"slug":"ciencia-1.s1.p12","orden":12,"grupo":"ciencia-1.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que se percibe directamente es una {{0}}; lo que se interpreta a partir de eso es una {{1}}; y una buena pregunta se puede responder con {{2}}.","banco":[{"id":"w1","texto":"observación"},{"id":"w2","texto":"inferencia"},{"id":"w3","texto":"datos"},{"id":"w4","texto":"opinión"},{"id":"w5","texto":"certeza"},{"id":"w6","texto":"gustos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para empezar a pensar como científico o científica."}},{"slug":"ciencia-1.s1.p13","orden":13,"grupo":"ciencia-1.s1.p13","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una inferencia siempre es falsa.","razones":[{"id":"r1","texto":"Porque puede ser correcta o no, y por eso se comprueba"},{"id":"r2","texto":"Porque las inferencias nunca se pueden comprobar"},{"id":"r3","texto":"Porque las inferencias son lo mismo que las observaciones"}]},"solucion":{"valor":false,"explicacion":"Las inferencias pueden ser correctas o no: por eso se comprueban. Muchas inferencias bien hechas terminan confirmadas con datos.","clave":["r1"]}}]},{"slug":"ciencia-1.s2","orden":2,"tipo":"leccion","titulo_es":"Hipótesis y experimentos","bajada_es":"Variables, grupo de control y repeticiones: cómo diseñar una prueba justa.","minutos":12,"pasos":[{"slug":"ciencia-1.s2.p1","orden":1,"grupo":"ciencia-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La hipótesis","cuerpo":["Una hipótesis es una explicación posible que se puede poner a prueba. Suele escribirse como una predicción: \"si agrego compost a las macetas, los porotos crecerán más que sin compost\".","Una buena hipótesis puede resultar falsa: si no hay ningún resultado posible que la contradiga, no se puede poner a prueba."]},"solucion":{}},{"slug":"ciencia-1.s2.p2","orden":2,"grupo":"ciencia-1.s2.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es una hipótesis que se puede poner a prueba?","opciones":[{"id":"o1","texto":"Regadas con lluvia, crecerán más que con agua de red"},{"id":"o2","texto":"Las plantas son seres maravillosos y llenos de vida"},{"id":"o3","texto":"Las plantas crecen y cambian con el paso del tiempo"},{"id":"o4","texto":"Algunas plantas pueden crecer más o menos que otras"}]},"solucion":{"clave":["o1"],"explicacion":"Una hipótesis útil predice algo concreto que podría no cumplirse.","por_opcion":{"o3":"Es cierto, pero no predice nada que se pueda comparar."}}},{"slug":"ciencia-1.s2.p3","orden":3,"grupo":"ciencia-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Variables","cuerpo":["En un experimento hay tres tipos de variables. La variable independiente es la que se cambia a propósito (con o sin compost). La variable dependiente es la que se mide para ver el efecto (la altura de los porotos). Y las variables controladas son todas las demás, que se mantienen iguales (la luz, el agua, la maceta, la semilla).","Si cambian varias cosas a la vez, no se puede saber cuál causó la diferencia."]},"solucion":{}},{"slug":"ciencia-1.s2.p4","orden":4,"grupo":"ciencia-1.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"En el experimento de los porotos con y sin compost, uní cada cosa con su tipo de variable.","izquierda":[{"id":"a1","texto":"Con o sin compost"},{"id":"a2","texto":"Altura de los porotos"},{"id":"a3","texto":"Cantidad de agua de riego"}],"derecha":[{"id":"b1","texto":"Variable independiente"},{"id":"b2","texto":"Variable dependiente"},{"id":"b3","texto":"Variable controlada"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Se cambia una sola cosa, se mide el efecto y todo lo demás se mantiene igual."}},{"slug":"ciencia-1.s2.p5","orden":5,"grupo":"ciencia-1.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El grupo de control","cuerpo":["Para saber si algo tiene efecto hay que compararlo con un grupo al que no se le aplica: el grupo de control. Si se agrega compost a todas las macetas, no hay con qué comparar. Se necesitan macetas iguales sin compost.","Y hacen falta varias macetas en cada grupo, no una: con una sola, una semilla mala puede arruinar la conclusión. Repetir es la forma de separar el efecto real del azar."]},"solucion":{}},{"slug":"ciencia-1.s2.p6","orden":6,"grupo":"ciencia-1.s2.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué hacen falta varias macetas en cada grupo.","items":[{"id":"i1","texto":"Cada semilla es un poco distinta"},{"id":"i2","texto":"Con una sola maceta por grupo, una semilla mala cambia todo"},{"id":"i3","texto":"Con muchas macetas, las diferencias al azar se compensan"},{"id":"i4","texto":"La comparación entre grupos se vuelve confiable"},{"id":"i5","texto":"Con más macetas las plantas crecen más rápido"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Repetir es la defensa contra el azar. Por eso los ensayos serios usan muchas repeticiones."}},{"slug":"ciencia-1.s2.p7","orden":7,"grupo":"ciencia-1.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para probar si el compost ayuda, alcanza con poner compost en una maceta y ver si la planta crece.","razones":[{"id":"r1","texto":"Porque sin comparación y sin repeticiones no se sabe si fue el compost"},{"id":"r2","texto":"Porque el compost nunca tiene efecto"},{"id":"r3","texto":"Porque las plantas no crecen en macetas"}]},"solucion":{"valor":false,"explicacion":"Sin grupo de control no se sabe si habría crecido igual sin compost. Y con una sola maceta, el azar puede engañar.","clave":["r1"]}},{"slug":"ciencia-1.s2.p8","orden":8,"grupo":"ciencia-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una prueba justa","cuerpo":["Un experimento es justo cuando la única diferencia entre los grupos es la variable que se estudia. Si las macetas con compost están al sol y las otras a la sombra, cualquier diferencia podría deberse a la luz.","Para evitar sesgos, a veces se asignan las macetas a cada grupo al azar, y quien mide no sabe cuál es cuál."]},"solucion":{}},{"slug":"ciencia-1.s2.p9","orden":9,"grupo":"ciencia-1.s2.p9","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este diseño de experimento y marcá los errores.","segmentos":[{"id":"s1","texto":"Queremos saber si el compost ayuda a crecer a los porotos."},{"id":"s2","texto":"Pusimos las macetas con compost al sol y las sin compost a la sombra."},{"id":"s3","texto":"Usamos 10 macetas por grupo, con el mismo tipo de semilla."},{"id":"s4","texto":"Las macetas con compost las regamos el doble."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una sola diferencia entre grupos. Todo lo demás, igual.","por_opcion":{"s2":"La luz cambia entre grupos: no se sabe si la diferencia es por el compost o por el sol.","s4":"El riego debe ser igual: si no, no se sabe qué causó la diferencia."}}},{"slug":"ciencia-1.s2.p10","orden":10,"grupo":"ciencia-1.s2.p10","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de un experimento sobre el compost.","items":[{"id":"i1","texto":"Formular la hipótesis"},{"id":"i2","texto":"Preparar dos grupos de macetas iguales"},{"id":"i3","texto":"Agregar compost solo a uno de los grupos"},{"id":"i4","texto":"Cuidar todas las macetas igual durante semanas"},{"id":"i5","texto":"Medir la altura y comparar los grupos"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Hipótesis, grupos, tratamiento, condiciones iguales y medición."}},{"slug":"ciencia-1.s2.p11","orden":11,"grupo":"ciencia-1.s2.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más confiable un experimento? Marcá todo.","opciones":[{"id":"o1","texto":"Tener un grupo de control"},{"id":"o2","texto":"Repetir con varias unidades por grupo"},{"id":"o3","texto":"Cambiar solo una variable"},{"id":"o4","texto":"Asignar al azar cuál unidad va a cada grupo"},{"id":"o5","texto":"Elegir para el tratamiento las plantas más lindas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Elegir las más lindas para el tratamiento sesga el resultado a favor de la hipótesis."}},{"slug":"ciencia-1.s2.p12","orden":12,"grupo":"ciencia-1.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alturas en cm con compost: 12, 14, 13, 15, 16. Sin compost: 10, 11, 9, 12, 13. ¿Cuántos cm más mide en promedio el grupo con compost?","unidad":"cm","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Promedio con compost: 14 cm. Sin compost: 11 cm. Diferencia: 3 cm. Comparar promedios de varios casos es más confiable que comparar una planta con otra."}},{"slug":"ciencia-1.s2.p12.v2","orden":12,"grupo":"ciencia-1.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alturas en cm con compost: 20, 22, 18, 21, 19. Sin compost: 17, 18, 16, 19, 15. ¿Cuántos cm más mide en promedio el grupo con compost?","unidad":"cm","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Promedio con compost: 20 cm. Sin compost: 17 cm. Diferencia: 3 cm. Comparar promedios de varios casos es más confiable que comparar una planta con otra."}},{"slug":"ciencia-1.s2.p12.v3","orden":12,"grupo":"ciencia-1.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alturas en cm con compost: 8, 9, 10, 9, 9. Sin compost: 7, 8, 7, 9, 9. ¿Cuántos cm más mide en promedio el grupo con compost?","unidad":"cm","decimales":1},"solucion":{"valor":1,"tolerancia":0.05,"explicacion":"Promedio con compost: 9 cm. Sin compost: 8 cm. Diferencia: 1 cm. Comparar promedios de varios casos es más confiable que comparar una planta con otra."}},{"slug":"ciencia-1.s2.p13","orden":13,"grupo":"ciencia-1.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un experimento se cambia la variable {{0}}, se mide la variable {{1}} y se compara con un grupo de {{2}}.","banco":[{"id":"w1","texto":"independiente"},{"id":"w2","texto":"dependiente"},{"id":"w3","texto":"control"},{"id":"w4","texto":"aleatoria"},{"id":"w5","texto":"favorita"},{"id":"w6","texto":"azar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La estructura básica de cualquier experimento justo."}},{"slug":"ciencia-1.s2.p14","orden":14,"grupo":"ciencia-1.s2.p14","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta variable del experimento del compost hay que mantenerla igual en los dos grupos o es la que se cambia?","grupos":[{"id":"g1","nombre":"Se mantiene igual"},{"id":"g2","nombre":"Se cambia a propósito"}],"items":[{"id":"i1","texto":"Tipo de semilla"},{"id":"i2","texto":"Presencia de compost"},{"id":"i3","texto":"Tamaño de la maceta"},{"id":"i4","texto":"Horas de sol"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g1"},"explicacion":"Todas menos una. Por eso se dice que se controlan las variables."}}]},{"slug":"ciencia-1.s3","orden":3,"tipo":"leccion","titulo_es":"Medir bien","bajada_es":"Exactitud, precisión, errores y muestras: por qué una medición mal hecha puede llevar a conclusiones falsas.","minutos":11,"pasos":[{"slug":"ciencia-1.s3.p1","orden":1,"grupo":"ciencia-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Exactitud y precisión","cuerpo":["Una medición es exacta cuando se acerca al valor real. Es precisa cuando, al repetirla, da valores parecidos entre sí. Un termómetro mal calibrado puede ser muy preciso (siempre marca 2 °C de más) pero no exacto.","Por eso los instrumentos se calibran, comparándolos con una referencia conocida."]},"solucion":{}},{"slug":"ciencia-1.s3.p2","orden":2,"grupo":"ciencia-1.s3.p2","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada situación con cómo es la medición.","izquierda":[{"id":"a1","texto":"Tres mediciones de 25,1; 25,0 y 25,2 °C, con valor real 25 °C"},{"id":"a2","texto":"Tres mediciones de 27,1; 27,0 y 27,2 °C, con valor real 25 °C"},{"id":"a3","texto":"Tres mediciones de 22; 28 y 25 °C, con valor real 25 °C"},{"id":"a4","texto":"Tres mediciones de 30; 21 y 34 °C, con valor real 25 °C"}],"derecha":[{"id":"b1","texto":"Exacta y precisa"},{"id":"b2","texto":"Precisa pero no exacta"},{"id":"b3","texto":"Exacta en promedio pero poco precisa"},{"id":"b4","texto":"Ni exacta ni precisa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Precisión es repetir parecido; exactitud es acertar al valor real. Se pueden tener una sin la otra."}},{"slug":"ciencia-1.s3.p3","orden":3,"grupo":"ciencia-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Errores","cuerpo":["Toda medición tiene algún error. Los errores al azar hacen que los valores se dispersen para un lado y para el otro; se reducen repitiendo y promediando. Los errores sistemáticos empujan siempre en la misma dirección —un termómetro al sol, una balanza mal tarada— y no se arreglan promediando: hay que corregir el método o el instrumento."]},"solucion":{}},{"slug":"ciencia-1.s3.p4","orden":4,"grupo":"ciencia-1.s3.p4","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un error al azar o sistemático?","grupos":[{"id":"g1","nombre":"Al azar"},{"id":"g2","nombre":"Sistemático"}],"items":[{"id":"i1","texto":"Pequeñas diferencias al leer una regla"},{"id":"i2","texto":"Un termómetro colgado al sol"},{"id":"i3","texto":"Variaciones de una medición a otra con el mismo instrumento"},{"id":"i4","texto":"Una balanza que marca 100 g aunque esté vacía"},{"id":"i5","texto":"Medir siempre el tránsito en el horario pico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Promediar arregla el azar, pero no el sesgo. Un termómetro al sol siempre va a marcar de más."}},{"slug":"ciencia-1.s3.p5","orden":5,"grupo":"ciencia-1.s3.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un termómetro está al sol, alcanza con medir muchas veces y promediar para corregir el error.","razones":[{"id":"r1","texto":"Porque es un error sistemático que empuja siempre hacia arriba"},{"id":"r2","texto":"Porque los termómetros no se ven afectados por el sol"},{"id":"r3","texto":"Porque promediar corrige cualquier error"}]},"solucion":{"valor":false,"explicacion":"Es un error sistemático: todas las mediciones van a estar altas. Promediar no lo corrige; hay que ponerlo a la sombra, como en las estaciones meteorológicas.","clave":["r1"]}},{"slug":"ciencia-1.s3.p6","orden":6,"grupo":"ciencia-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La muestra","cuerpo":["Casi nunca se puede medir todo: todos los árboles de una ciudad, todas las casas, toda el agua de un río. Se mide una muestra y se generaliza. Para que eso funcione, la muestra tiene que ser suficientemente grande y representativa: parecida al conjunto en lo que importa.","Si se encuesta solo a los vecinos de un barrio rico sobre el acceso al agua, la conclusión no vale para toda la ciudad."]},"solucion":{}},{"slug":"ciencia-1.s3.p7","orden":7,"grupo":"ciencia-1.s3.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Querés saber cuánta basura genera por día cada casa de tu ciudad. ¿Qué muestra es mejor?","opciones":[{"id":"o1","texto":"Casas de distintos barrios elegidas al azar"},{"id":"o2","texto":"Las casas de tu cuadra"},{"id":"o3","texto":"Las casas de tus amigos"},{"id":"o4","texto":"Solo las casas más grandes, que generan más"}]},"solucion":{"clave":["o1"],"explicacion":"Al azar y de distintos barrios: así la muestra se parece a la ciudad.","por_opcion":{"o3":"Se parecen a vos: la muestra estaría sesgada."}}},{"slug":"ciencia-1.s3.p8","orden":8,"grupo":"ciencia-1.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una muestra sesgada lleva a una conclusión falsa.","items":[{"id":"i1","texto":"Se encuesta solo a personas en un gimnasio"},{"id":"i2","texto":"La muestra tiene más gente que hace ejercicio"},{"id":"i3","texto":"El resultado muestra mucha actividad física"},{"id":"i4","texto":"Se concluye que toda la ciudad hace mucho ejercicio"},{"id":"i5","texto":"La muestra del gimnasio representa bien a toda la ciudad"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El problema no es el cálculo: es a quién se le preguntó."}},{"slug":"ciencia-1.s3.p9","orden":9,"grupo":"ciencia-1.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cinco mediciones repetidas de lo mismo dieron: 120, 118, 122, 119, 121. ¿Cuál es el promedio?","unidad":"","decimales":1},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"(120 + 118 + 122 + 119 + 121) ÷ 5 = 120. Repetir y promediar reduce el efecto de los errores al azar."}},{"slug":"ciencia-1.s3.p9.v2","orden":9,"grupo":"ciencia-1.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cinco mediciones repetidas de lo mismo dieron: 48, 52, 50, 49, 51. ¿Cuál es el promedio?","unidad":"","decimales":1},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(48 + 52 + 50 + 49 + 51) ÷ 5 = 50. Repetir y promediar reduce el efecto de los errores al azar."}},{"slug":"ciencia-1.s3.p9.v3","orden":9,"grupo":"ciencia-1.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cinco mediciones repetidas de lo mismo dieron: 7, 9, 8, 8, 8. ¿Cuál es el promedio?","unidad":"","decimales":1},"solucion":{"valor":8,"tolerancia":0.16,"explicacion":"(7 + 9 + 8 + 8 + 8) ÷ 5 = 8. Repetir y promediar reduce el efecto de los errores al azar."}},{"slug":"ciencia-1.s3.p10","orden":10,"grupo":"ciencia-1.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué mejora la calidad de una medición? Marcá todo.","opciones":[{"id":"o1","texto":"Calibrar el instrumento"},{"id":"o2","texto":"Repetir la medición varias veces"},{"id":"o3","texto":"Medir siempre con el mismo método"},{"id":"o4","texto":"Anotar las condiciones en que se midió"},{"id":"o5","texto":"Redondear los números para que queden lindos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Calibrar, repetir, estandarizar y registrar. Redondear de más pierde información."}},{"slug":"ciencia-1.s3.p11","orden":11,"grupo":"ciencia-1.s3.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas muestras de la más confiable a la menos, para estimar el consumo de agua de una ciudad.","items":[{"id":"i1","texto":"1.000 casas elegidas al azar en toda la ciudad"},{"id":"i2","texto":"1.000 casas de un solo barrio"},{"id":"i3","texto":"20 casas elegidas al azar"},{"id":"i4","texto":"Tu casa"}],"extremos":["Más confiable","Menos confiable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Tamaño y representatividad importan los dos. Mil casas de un barrio no dicen lo mismo que mil al azar.","valores":{"i1":"grande y representativa","i2":"grande pero sesgada","i3":"representativa pero chica","i4":"un solo caso"}}},{"slug":"ciencia-1.s3.p12","orden":12,"grupo":"ciencia-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta conclusión y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"Medimos la temperatura con un termómetro calibrado, a la sombra."},{"id":"s2","texto":"Le preguntamos a 5 compañeros y el 100 % recicla: en la ciudad todos reciclan."},{"id":"s3","texto":"Repetimos cada medición tres veces y promediamos."},{"id":"s4","texto":"La balanza marcaba 50 g vacía, pero no importa porque pesamos muchas veces."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Muestras y errores: dos lugares donde se esconden las conclusiones falsas.","por_opcion":{"s2":"Muestra chica y no representativa: no se puede generalizar a la ciudad.","s4":"Es un error sistemático: hay que tarar la balanza o restar esos 50 g."}}},{"slug":"ciencia-1.s3.p13","orden":13,"grupo":"ciencia-1.s3.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una medición cercana al valor real es {{0}}; una que da valores parecidos al repetirla es {{1}}; y una muestra tiene que ser {{2}}.","banco":[{"id":"w1","texto":"exacta"},{"id":"w2","texto":"precisa"},{"id":"w3","texto":"representativa"},{"id":"w4","texto":"rápida"},{"id":"w5","texto":"redonda"},{"id":"w6","texto":"enorme"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres palabras para evaluar cualquier dato."}}]},{"slug":"ciencia-1.s4","orden":4,"tipo":"leccion","titulo_es":"Correlación no es causa","bajada_es":"Cuando dos cosas suben juntas, no siempre una causa la otra. Terceras variables, azar y causas inversas.","minutos":11,"pasos":[{"slug":"ciencia-1.s4.p1","orden":1,"grupo":"ciencia-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ir juntas no es causar","cuerpo":["Dos cosas están correlacionadas cuando cambian juntas: cuando una sube, la otra también sube (o baja). Pero eso no quiere decir que una cause la otra. En verano se venden más helados y también hay más ahogamientos en el mar. Los helados no causan ahogamientos: el calor hace que haya más helados y más gente bañándose.","Ese calor es una tercera variable, o variable de confusión: causa las dos cosas y hace que parezcan relacionadas."]},"solucion":{}},{"slug":"ciencia-1.s4.p2","orden":2,"grupo":"ciencia-1.s4.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En verano suben las ventas de helado y también los casos de insolación. ¿Cuál es la explicación más probable?","opciones":[{"id":"o1","texto":"El calor causa las dos cosas"},{"id":"o2","texto":"Los helados causan insolación"},{"id":"o3","texto":"La insolación hace que la gente coma helado"},{"id":"o4","texto":"Es pura casualidad y no hay relación"}]},"solucion":{"clave":["o1"],"explicacion":"Una tercera variable, el calor, explica las dos. Es el caso típico de correlación sin causalidad directa.","por_opcion":{"o3":"Es posible que alguien con calor coma helado, pero la causa común de las dos cosas es el calor."}}},{"slug":"ciencia-1.s4.p3","orden":3,"grupo":"ciencia-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres trampas","cuerpo":["Cuando dos cosas aparecen juntas, hay varias posibilidades además de que A cause B: puede ser que B cause A (causa inversa), que una tercera variable cause las dos (confusión) o que sea casualidad, sobre todo si se buscan muchas relaciones a la vez.","Para saber si hay causa, hacen falta experimentos, un mecanismo que lo explique o muchos estudios que descarten las otras opciones."]},"solucion":{}},{"slug":"ciencia-1.s4.p4","orden":4,"grupo":"ciencia-1.s4.p4","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada caso con la trampa que representa.","izquierda":[{"id":"a1","texto":"Barrios con más bomberos tienen más incendios"},{"id":"a2","texto":"Ciudades con más plazas tienen más perros"},{"id":"a3","texto":"Un año la venta de paraguas coincidió con goles de un equipo"},{"id":"a4","texto":"Más horas de estudio, mejores notas"}],"derecha":[{"id":"b1","texto":"Causa inversa: más incendios llevan a poner más bomberos"},{"id":"b2","texto":"Tercera variable: el tamaño de la ciudad"},{"id":"b3","texto":"Casualidad"},{"id":"b4","texto":"Probable causa, confirmable con más evidencia"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"No todo lo que va junto se explica igual. Pensar las alternativas es parte del método."}},{"slug":"ciencia-1.s4.p5","orden":5,"grupo":"ciencia-1.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si dos cosas están muy correlacionadas, entonces una causa la otra.","razones":[{"id":"r1","texto":"Porque puede haber otra variable, causa inversa o casualidad"},{"id":"r2","texto":"Porque la correlación siempre es casualidad"},{"id":"r3","texto":"Porque las cosas correlacionadas nunca están relacionadas"}]},"solucion":{"valor":false,"explicacion":"Puede haber causa inversa, una tercera variable o casualidad. La correlación es una pista, no una prueba de causa.","clave":["r1"]}},{"slug":"ciencia-1.s4.p6","orden":6,"grupo":"ciencia-1.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando sí hay causa","cuerpo":["A veces la correlación sí refleja una causa, y la ciencia lo muestra con varias líneas de evidencia. Que el aumento del CO₂ causa calentamiento se sabe no solo porque las dos cosas subieron juntas, sino porque hay un mecanismo físico conocido desde el siglo XIX (el CO₂ absorbe radiación infrarroja), experimentos de laboratorio, mediciones satelitales de la energía que sale de la Tierra y modelos que solo reproducen el calentamiento observado si incluyen los gases emitidos por las personas."]},"solucion":{}},{"slug":"ciencia-1.s4.p7","orden":7,"grupo":"ciencia-1.s4.p7","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué tipos de evidencia muestran que el CO₂ emitido por las personas causa calentamiento? Marcá todos.","opciones":[{"id":"o1","texto":"Un mecanismo físico conocido: el CO₂ absorbe radiación infrarroja"},{"id":"o2","texto":"Experimentos de laboratorio"},{"id":"o3","texto":"Mediciones satelitales de la energía que sale de la Tierra"},{"id":"o4","texto":"Modelos que solo reproducen el calentamiento con esos gases"},{"id":"o5","texto":"Que en un invierno hizo más calor de lo normal"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un solo invierno no prueba nada. La causa se establece con varias líneas de evidencia que coinciden."}},{"slug":"ciencia-1.s4.p8","orden":8,"grupo":"ciencia-1.s4.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se pasa de una correlación a una causa establecida.","items":[{"id":"i1","texto":"Se observa que dos cosas cambian juntas"},{"id":"i2","texto":"Se proponen explicaciones posibles"},{"id":"i3","texto":"Se buscan un mecanismo y experimentos"},{"id":"i4","texto":"Se descartan terceras variables y la causa inversa"},{"id":"i5","texto":"Muchas líneas de evidencia coinciden"},{"id":"i6","texto":"Se publica la correlación y queda probado"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La causa se construye con evidencia acumulada, no con un gráfico."}},{"slug":"ciencia-1.s4.p9","orden":9,"grupo":"ciencia-1.s4.p9","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué conclusión se puede sacar en cada caso?","grupos":[{"id":"g1","nombre":"Solo correlación (no alcanza para causa)"},{"id":"g2","nombre":"Causa con evidencia experimental"}],"items":[{"id":"i1","texto":"En los barrios con más árboles vive gente con más ingresos"},{"id":"i2","texto":"En un ensayo con grupos al azar, el compost aumentó el crecimiento"},{"id":"i3","texto":"En los días de más tránsito hay más consultas por asma"},{"id":"i4","texto":"En laboratorio, más CO₂ absorbe más radiación infrarroja"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Los experimentos con grupos al azar y los mecanismos físicos son las pruebas más fuertes de causa."}},{"slug":"ciencia-1.s4.p10","orden":10,"grupo":"ciencia-1.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mes se vendieron 100 mil helados y hubo 20 insolaciones en una ciudad. Un periodista calcula 5 mil helados por insolación. ¿Cuántos mil helados por insolación dice?","unidad":"mil helados","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"100 ÷ 20 = 5. La cuenta está bien, pero no significa nada: los helados no causan insolación. Un número bien calculado puede no tener sentido."}},{"slug":"ciencia-1.s4.p10.v2","orden":10,"grupo":"ciencia-1.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mes se vendieron 150 mil helados y hubo 30 insolaciones en una ciudad. Un periodista calcula 5 mil helados por insolación. ¿Cuántos mil helados por insolación dice?","unidad":"mil helados","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"150 ÷ 30 = 5. La cuenta está bien, pero no significa nada: los helados no causan insolación. Un número bien calculado puede no tener sentido."}},{"slug":"ciencia-1.s4.p10.v3","orden":10,"grupo":"ciencia-1.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mes se vendieron 80 mil helados y hubo 16 insolaciones en una ciudad. Un periodista calcula 5 mil helados por insolación. ¿Cuántos mil helados por insolación dice?","unidad":"mil helados","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"80 ÷ 16 = 5. La cuenta está bien, pero no significa nada: los helados no causan insolación. Un número bien calculado puede no tener sentido."}},{"slug":"ciencia-1.s4.p11","orden":11,"grupo":"ciencia-1.s4.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un estudio encuentra que quienes toman más café viven más años. ¿Qué pregunta conviene hacerse primero?","opciones":[{"id":"o1","texto":"¿Hay otra variable que explique las dos cosas?"},{"id":"o2","texto":"¿Cuántas tazas de café tengo que tomar para vivir más?"},{"id":"o3","texto":"¿Qué marca de café tomaban los que vivieron más?"},{"id":"o4","texto":"¿Por qué el café es tan bueno para la salud de todos?"}]},"solucion":{"clave":["o1"],"explicacion":"Ingresos, hábitos o salud previa podrían explicar las dos cosas. Antes de concluir causa, se buscan terceras variables.","por_opcion":{"o3":"Primero hay que ver si la relación es causal; la marca es un detalle posterior."}}},{"slug":"ciencia-1.s4.p12","orden":12,"grupo":"ciencia-1.s4.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas ayudan a evaluar si una correlación es causa? Marcá todas.","opciones":[{"id":"o1","texto":"¿Podría ser al revés, que B cause A?"},{"id":"o2","texto":"¿Hay una tercera variable que cause las dos?"},{"id":"o3","texto":"¿Hay un mecanismo que lo explique?"},{"id":"o4","texto":"¿Se confirmó con experimentos o muchos estudios?"},{"id":"o5","texto":"¿El gráfico tiene colores lindos?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro preguntas que desarman la mayoría de las conclusiones apuradas."}},{"slug":"ciencia-1.s4.p13","orden":13,"grupo":"ciencia-1.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo que no se puede concluir de los datos.","segmentos":[{"id":"s1","texto":"Los barrios con más árboles tienen menos casos de golpes de calor."},{"id":"s2","texto":"Plantar un árbol evita que tu familia tenga un golpe de calor."},{"id":"s3","texto":"Los investigadores midieron temperaturas más bajas bajo los árboles."},{"id":"s4","texto":"Por lo tanto, los golpes de calor solo dependen de los árboles."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los datos pueden ser ciertos y la conclusión exagerada. Leer con cuidado es separar las dos cosas.","por_opcion":{"s2":"Es una correlación de barrios; no prueba el efecto individual y puede haber otras variables, como el ingreso.","s4":"Dependen de muchas cosas: edad, salud, vivienda, trabajo, agua."}}},{"slug":"ciencia-1.s4.p14","orden":14,"grupo":"ciencia-1.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Que dos cosas cambien juntas es una {{0}}; una variable que causa las dos es una variable de {{1}}; y para probar causa ayudan los {{2}}.","banco":[{"id":"w1","texto":"correlación"},{"id":"w2","texto":"confusión"},{"id":"w3","texto":"experimentos"},{"id":"w4","texto":"causa"},{"id":"w5","texto":"control"},{"id":"w6","texto":"rumores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea más importante de la lección, en una sola línea."}}]},{"slug":"ciencia-1.s5","orden":5,"tipo":"leccion","titulo_es":"Cómo avanza la ciencia","bajada_es":"Revisión por pares, réplica, consenso e incertidumbre: por qué la ciencia es confiable justamente porque se corrige.","minutos":12,"pasos":[{"slug":"ciencia-1.s5.p1","orden":1,"grupo":"ciencia-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Revisión y réplica","cuerpo":["Cuando un equipo científico obtiene un resultado, lo publica en una revista especializada. Antes de publicarse, otros especialistas lo revisan en busca de errores: es la revisión por pares. Después, otros equipos intentan repetir el estudio (réplica) o lo ponen a prueba con otros métodos.","Un resultado aislado puede estar equivocado. Un resultado que muchos equipos independientes confirman con métodos distintos es mucho más confiable."]},"solucion":{}},{"slug":"ciencia-1.s5.p2","orden":2,"grupo":"ciencia-1.s5.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido típico de un resultado científico.","items":[{"id":"i1","texto":"Un equipo investiga y obtiene un resultado"},{"id":"i2","texto":"Lo envía a una revista especializada"},{"id":"i3","texto":"Otros especialistas lo revisan antes de publicarlo"},{"id":"i4","texto":"Se publica"},{"id":"i5","texto":"Otros equipos intentan replicarlo o ponerlo a prueba"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La ciencia no termina con la publicación: ahí empieza la prueba de fuego."}},{"slug":"ciencia-1.s5.p3","orden":3,"grupo":"ciencia-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El consenso","cuerpo":["Cuando la gran mayoría de los especialistas coincide en una conclusión, después de revisar toda la evidencia, se habla de consenso científico. No es una votación ni una opinión de moda: es el resultado de miles de estudios que apuntan en la misma dirección.","Sobre el cambio climático, distintos estudios encontraron que alrededor del 97 % o más de los científicos del clima que publican sobre el tema coinciden en que el calentamiento reciente es causado por las actividades humanas. El IPCC, que reúne a miles de especialistas, lo resume así en sus informes."],"destacado":{"valor":"≥ 97 %","texto":"de los científicos del clima que publican sobre el tema coincide en que el calentamiento reciente es causado por las personas."}},"solucion":{}},{"slug":"ciencia-1.s5.p4","orden":4,"grupo":"ciencia-1.s5.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El consenso científico es una votación entre científicos sobre lo que prefieren creer.","razones":[{"id":"r1","texto":"Porque surge de mucha evidencia independiente que coincide"},{"id":"r2","texto":"Porque los científicos votan una vez por año"},{"id":"r3","texto":"Porque el consenso se decide por mayoría política"}]},"solucion":{"valor":false,"explicacion":"Es la coincidencia a la que se llega después de revisar muchísima evidencia de estudios independientes. No se decide por preferencia, sino por datos.","clave":["r1"]}},{"slug":"ciencia-1.s5.p5","orden":5,"grupo":"ciencia-1.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Incertidumbre no es ignorancia","cuerpo":["La ciencia expresa sus resultados con incertidumbre: rangos y probabilidades. Decir \"el calentamiento será de entre 2 y 3 °C con tal escenario\" no significa que no se sepa nada: significa que se conoce con bastante precisión dentro de ese rango.","Que haya incertidumbre en los detalles no quiere decir que haya duda sobre lo principal. Se sabe con certeza que la Tierra se calentó y por qué; hay más incertidumbre sobre cuánto exactamente se calentará cada región."]},"solucion":{}},{"slug":"ciencia-1.s5.p6","orden":6,"grupo":"ciencia-1.s5.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un informe dice que el calentamiento será \"probablemente\" de entre 2 y 3 °C en cierto escenario. ¿Qué significa?","opciones":[{"id":"o1","texto":"Que los científicos estiman un rango con alta probabilidad"},{"id":"o2","texto":"Que los científicos no tienen idea de lo que va a pasar"},{"id":"o3","texto":"Que va a ser exactamente 2,5 °C"},{"id":"o4","texto":"Que el calentamiento podría ser negativo"}]},"solucion":{"clave":["o1"],"explicacion":"La incertidumbre bien expresada es una fortaleza: dice qué tan seguros estamos.","por_opcion":{"o3":"Es un rango, no un valor exacto: expresa la incertidumbre honestamente."}}},{"slug":"ciencia-1.s5.p7","orden":7,"grupo":"ciencia-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Corregirse es una virtud","cuerpo":["La ciencia cambia cuando aparece evidencia nueva. Eso no es una debilidad: es lo que la hace confiable. El agujero de ozono, por ejemplo, se detectó en la década de 1980, se identificaron sus causas (los clorofluorocarbonos, CFC), el mundo los prohibió con el Protocolo de Montreal y hoy la capa de ozono se está recuperando lentamente.","Quien nunca cambia de opinión frente a la evidencia no está haciendo ciencia."]},"solucion":{}},{"slug":"ciencia-1.s5.p8","orden":8,"grupo":"ciencia-1.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena del caso del agujero de ozono.","items":[{"id":"i1","texto":"Se detecta una disminución del ozono sobre la Antártida"},{"id":"i2","texto":"Los científicos identifican a los CFC como causa"},{"id":"i3","texto":"Los países firman el Protocolo de Montreal"},{"id":"i4","texto":"Se dejan de producir los CFC"},{"id":"i5","texto":"La capa de ozono empieza a recuperarse"},{"id":"i6","texto":"El agujero se cerró solo sin que nadie hiciera nada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un ejemplo de ciencia que detecta, explica y guía una solución que funciona."}},{"slug":"ciencia-1.s5.p9","orden":9,"grupo":"ciencia-1.s5.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una señal de buena ciencia o de mala ciencia?","grupos":[{"id":"g1","nombre":"Buena ciencia"},{"id":"g2","nombre":"Mala ciencia"}],"items":[{"id":"i1","texto":"Publicar los datos para que otros los revisen"},{"id":"i2","texto":"Ocultar los datos para que nadie los revise"},{"id":"i3","texto":"Cambiar la conclusión ante evidencia nueva"},{"id":"i4","texto":"Elegir solo los resultados que convienen"},{"id":"i5","texto":"Informar la incertidumbre de los resultados"},{"id":"i6","texto":"Presentar un solo estudio como prueba definitiva"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Transparencia, humildad frente a la evidencia y honestidad sobre la incertidumbre."}},{"slug":"ciencia-1.s5.p10","orden":10,"grupo":"ciencia-1.s5.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una conclusión científica sea muy confiable? Marcá todo.","opciones":[{"id":"o1","texto":"Que muchos equipos independientes la confirmen"},{"id":"o2","texto":"Que se base en métodos distintos que coinciden"},{"id":"o3","texto":"Que haya pasado revisión por pares"},{"id":"o4","texto":"Que exista un mecanismo que la explique"},{"id":"o5","texto":"Que la diga una persona famosa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La fama no es evidencia. La coincidencia de muchos estudios independientes, sí."}},{"slug":"ciencia-1.s5.p11","orden":11,"grupo":"ciencia-1.s5.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Revisión por pares"},{"id":"a2","texto":"Réplica"},{"id":"a3","texto":"Consenso"},{"id":"a4","texto":"Incertidumbre"}],"derecha":[{"id":"b1","texto":"Especialistas revisan un trabajo antes de publicarlo"},{"id":"b2","texto":"Otro equipo repite el estudio para ver si da igual"},{"id":"b3","texto":"Coincidencia de la mayoría de especialistas basada en la evidencia"},{"id":"b4","texto":"Rango dentro del cual se estima un valor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro palabras para entender por qué se puede confiar en la ciencia sin que sea infalible."}},{"slug":"ciencia-1.s5.p12","orden":12,"grupo":"ciencia-1.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario en redes y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los científicos revisan los trabajos de otros antes de publicarlos."},{"id":"s2","texto":"Si la ciencia cambia de opinión, es que no sirve."},{"id":"s3","texto":"El Protocolo de Montreal ayudó a recuperar la capa de ozono."},{"id":"s4","texto":"Como hay incertidumbre, no se sabe si el clima está cambiando."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Confiar en la ciencia no es creer ciegamente: es entender cómo se construye.","por_opcion":{"s2":"Corregirse ante evidencia nueva es justamente lo que la hace confiable.","s4":"La incertidumbre está en los detalles; que el clima cambia por las personas está establecido."}}},{"slug":"ciencia-1.s5.p13","orden":13,"grupo":"ciencia-1.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Antes de publicarse, un estudio pasa por la revisión por {{0}}; cuando otros lo repiten se habla de {{1}}; y el agujero de ozono se enfrentó con el Protocolo de {{2}}.","banco":[{"id":"w1","texto":"pares"},{"id":"w2","texto":"réplica"},{"id":"w3","texto":"Montreal"},{"id":"w4","texto":"votos"},{"id":"w5","texto":"copia"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre cómo avanza y se aplica la ciencia."}},{"slug":"ciencia-1.s5.p14","orden":14,"grupo":"ciencia-1.s5.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los científicos del clima que publican sobre el tema coincide en que el calentamiento reciente es causado por las personas.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":97,"banda":"lineal","explicacion":"Alrededor del 97 % o más, según varios estudios que analizaron miles de publicaciones. Es uno de los consensos más sólidos de la ciencia actual."}}]},{"slug":"ciencia-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: cómo sabemos lo que sabemos","bajada_es":"Observación, experimentos, mediciones, causalidad y consenso, mezclados.","minutos":8,"pasos":[{"slug":"ciencia-1.s6.p1","orden":1,"grupo":"ciencia-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Cómo sabemos lo que sabemos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"ciencia-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el experimento de las macetas","bajada_es":"Un curso quiere probar si el agua de lluvia es mejor que el agua de red para las plantas. Revisá su diseño y sus conclusiones.","minutos":10,"pasos":[{"slug":"ciencia-1.s7.p1","orden":1,"grupo":"ciencia-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El diseño original","cuerpo":["Un curso puso 2 macetas: una regada con agua de lluvia, junto a la ventana, y otra regada con agua de red, en un rincón. A la de lluvia le pusieron una semilla de girasol y a la de red, una de poroto. Después de un mes, la de lluvia medía 30 cm y la de red 12 cm. Concluyeron: \"el agua de lluvia hace crecer más del doble a las plantas\"."]},"solucion":{}},{"slug":"ciencia-1.s7.p2","orden":2,"grupo":"ciencia-1.s7.p2","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas tiene el diseño? Marcá todos.","opciones":[{"id":"o1","texto":"Solo una maceta por grupo"},{"id":"o2","texto":"Distinta luz entre las macetas"},{"id":"o3","texto":"Distinta especie de planta en cada maceta"},{"id":"o4","texto":"No se controlaron otras variables, como la cantidad de agua"},{"id":"o5","texto":"Midieron la altura con una regla"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Tres cosas cambiaron a la vez: el agua, la luz y la especie. Así no se sabe qué causó la diferencia."}},{"slug":"ciencia-1.s7.p3","orden":3,"grupo":"ciencia-1.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conclusión se puede sacar de verdad del experimento original?","opciones":[{"id":"o1","texto":"Ninguna sobre el agua, porque cambiaron varias cosas"},{"id":"o2","texto":"Que el agua de lluvia hace crecer el doble a cualquier planta"},{"id":"o3","texto":"Que el agua de red es tóxica para las plantas"},{"id":"o4","texto":"Que los girasoles prefieren el agua de lluvia"}]},"solucion":{"clave":["o1"],"explicacion":"Con variables mezcladas, el experimento no responde la pregunta. Hay que rediseñarlo.","por_opcion":{"o3":"No hay evidencia de eso: la de red tenía otra especie y menos luz."}}},{"slug":"ciencia-1.s7.p4","orden":4,"grupo":"ciencia-1.s7.p4","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos del diseño corregido.","items":[{"id":"i1","texto":"Elegir una sola especie y semillas parecidas"},{"id":"i2","texto":"Preparar 10 macetas iguales para cada tipo de agua"},{"id":"i3","texto":"Asignar al azar qué maceta recibe cada agua"},{"id":"i4","texto":"Ponerlas todas con la misma luz y regarlas con la misma cantidad"},{"id":"i5","texto":"Medir la altura de todas y comparar los promedios"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una sola diferencia entre grupos, repeticiones, azar y comparación de promedios."}},{"slug":"ciencia-1.s7.p5","orden":5,"grupo":"ciencia-1.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el diseño corregido, el promedio con agua de lluvia fue 18,4 cm y con agua de red 17,9 cm. ¿Cuál es la diferencia en cm?","unidad":"cm","decimales":1},"solucion":{"valor":0.5,"tolerancia":0.05,"explicacion":"18,4 − 17,9 = 0,5 cm. Una diferencia chica, que puede ser del azar: muy lejos del \"doble\" del primer experimento."}},{"slug":"ciencia-1.s7.p5.v2","orden":5,"grupo":"ciencia-1.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el diseño corregido, el promedio con agua de lluvia fue 20,2 cm y con agua de red 19,8 cm. ¿Cuál es la diferencia en cm?","unidad":"cm","decimales":1},"solucion":{"valor":0.4,"tolerancia":0.05,"explicacion":"20,2 − 19,8 = 0,4 cm. Una diferencia chica, que puede ser del azar: muy lejos del \"doble\" del primer experimento."}},{"slug":"ciencia-1.s7.p5.v3","orden":5,"grupo":"ciencia-1.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el diseño corregido, el promedio con agua de lluvia fue 15,6 cm y con agua de red 15,1 cm. ¿Cuál es la diferencia en cm?","unidad":"cm","decimales":1},"solucion":{"valor":0.5,"tolerancia":0.05,"explicacion":"15,6 − 15,1 = 0,5 cm. Una diferencia chica, que puede ser del azar: muy lejos del \"doble\" del primer experimento."}},{"slug":"ciencia-1.s7.p6","orden":6,"grupo":"ciencia-1.s7.p6","tipo":"vf","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Con el diseño corregido, una diferencia de medio centímetro entre promedios prueba que el agua de lluvia es mejor.","razones":[{"id":"r1","texto":"Porque una diferencia chica puede deberse al azar"},{"id":"r2","texto":"Porque medio centímetro es una diferencia enorme"},{"id":"r3","texto":"Porque el diseño corregido sigue teniendo tres variables mezcladas"}]},"solucion":{"valor":false,"explicacion":"Una diferencia tan chica puede deberse al azar. Habría que ver cuánto varían las plantas dentro de cada grupo, repetir el experimento o usar más macetas.","clave":["r1"]}},{"slug":"ciencia-1.s7.p7","orden":7,"grupo":"ciencia-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las conclusiones que propone el curso después del diseño corregido.","grupos":[{"id":"g1","nombre":"Bien fundada"},{"id":"g2","nombre":"No fundada"}],"items":[{"id":"i1","texto":"Con estas condiciones, no encontramos una diferencia clara"},{"id":"i2","texto":"El agua de red es mala para todas las plantas"},{"id":"i3","texto":"Habría que repetir con más macetas para estar seguros"},{"id":"i4","texto":"El primer experimento demostró que la lluvia duplica el crecimiento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Una buena conclusión dice lo que los datos muestran, con sus límites."}},{"slug":"ciencia-1.s7.p8","orden":8,"grupo":"ciencia-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El curso escribe su informe final. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En el primer diseño cambiaron varias variables a la vez."},{"id":"s2","texto":"El primer experimento probó que la lluvia duplica el crecimiento."},{"id":"s3","texto":"Con el diseño corregido, la diferencia fue muy chica."},{"id":"s4","texto":"Como no encontramos diferencia, la ciencia no sirve."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reconocer los errores del primer diseño y aceptar un resultado \"aburrido\" es hacer ciencia de verdad.","por_opcion":{"s2":"No probó nada sobre el agua: la luz y la especie también cambiaban.","s4":"No encontrar diferencia también es un resultado válido: responde la pregunta."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"ciencia-2","rama":"ciencia","orden":2,"nivel":1,"titulo_es":"Leer gráficos y datos","bajada_es":"Un gráfico puede aclarar o engañar. Cómo elegir el gráfico justo, ver una tendencia en medio del ruido y no caer en trampas con porcentajes.","objetivos_es":["Elegir el tipo de gráfico adecuado para cada pregunta","Distinguir una tendencia de la variabilidad de corto plazo","Detectar recursos visuales que distorsionan un gráfico","Elegir entre promedio y mediana según los datos","Interpretar porcentajes, puntos porcentuales y tasas por persona"],"repasa":["ciencia-1","tronco-2"],"requiere_tronco":1,"fuentes":["noaa-co2","nasa-evidencia","owid-co2","chequeado","ipcc-ar6-syr"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"ciencia-2.s1","orden":1,"tipo":"leccion","titulo_es":"Cada gráfico para su pregunta","bajada_es":"Barras, líneas, tortas y puntos: qué muestra bien cada uno y cuándo conviene una tabla.","minutos":11,"pasos":[{"slug":"ciencia-2.s1.p1","orden":1,"grupo":"ciencia-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuatro gráficos básicos","cuerpo":["Los gráficos de barras sirven para comparar cantidades entre categorías: emisiones de distintos países, consumo de distintos aparatos. Los gráficos de líneas muestran cómo cambia algo en el tiempo: la temperatura año a año, el CO₂ mes a mes. Los gráficos de torta muestran partes de un todo, y funcionan bien solo con pocas partes. Los gráficos de dispersión (puntos) muestran si dos variables se relacionan.","Cuando hay que ver números exactos, a veces una tabla es mejor que cualquier gráfico."]},"solucion":{}},{"slug":"ciencia-2.s1.p2","orden":2,"grupo":"ciencia-2.s1.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pregunta con el gráfico más adecuado.","izquierda":[{"id":"a1","texto":"¿Cómo cambió la temperatura media entre 1900 y hoy?"},{"id":"a2","texto":"¿Qué aparato de la casa consume más energía?"},{"id":"a3","texto":"¿Qué parte de la basura son orgánicos, plásticos y papel?"},{"id":"a4","texto":"¿Tienen menos temperatura las cuadras con más árboles?"}],"derecha":[{"id":"b1","texto":"Líneas"},{"id":"b2","texto":"Barras"},{"id":"b3","texto":"Torta"},{"id":"b4","texto":"Dispersión (puntos)"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Tiempo con líneas, comparación con barras, partes con torta, relación con puntos."}},{"slug":"ciencia-2.s1.p3","orden":3,"grupo":"ciencia-2.s1.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de gráfico conviene para mostrar esto?","grupos":[{"id":"g1","nombre":"Líneas"},{"id":"g2","nombre":"Barras"},{"id":"g3","nombre":"Dispersión"}],"items":[{"id":"i1","texto":"El nivel del río Paraná mes a mes durante cinco años"},{"id":"i2","texto":"Huella de carbono de cinco alimentos"},{"id":"i3","texto":"Relación entre árboles por cuadra y temperatura"},{"id":"i4","texto":"El CO₂ del aire desde 1960"},{"id":"i5","texto":"Lluvia total de cada provincia en un año"},{"id":"i6","texto":"Relación entre tamaño de la casa y consumo de gas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"La pregunta define el gráfico. Un gráfico lindo pero equivocado confunde."}},{"slug":"ciencia-2.s1.p4","orden":4,"grupo":"ciencia-2.s1.p4","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un gráfico de torta es una buena opción para mostrar cómo cambió la temperatura año a año.","razones":[{"id":"r1","texto":"Porque las tortas muestran partes de un todo, no cambios en el tiempo"},{"id":"r2","texto":"Porque la temperatura no se puede graficar"},{"id":"r3","texto":"Porque las tortas solo sirven para mostrar dinero"}]},"solucion":{"valor":false,"explicacion":"Las tortas muestran partes de un todo en un momento. Para cambios en el tiempo, lo adecuado es un gráfico de líneas.","clave":["r1"]}},{"slug":"ciencia-2.s1.p5","orden":5,"grupo":"ciencia-2.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las partes de un gráfico","cuerpo":["Antes de interpretar un gráfico hay que leer sus partes: el título (qué muestra), los ejes (qué variable va en cada uno), las unidades (grados, toneladas, porcentaje), la escala (de cuánto en cuánto van las marcas) y la fuente (de dónde salen los datos).","Muchos errores de interpretación vienen de saltear estos pasos y mirar solo la forma del dibujo."]},"solucion":{}},{"slug":"ciencia-2.s1.p6","orden":6,"grupo":"ciencia-2.s1.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo conviene leer un gráfico nuevo.","items":[{"id":"i1","texto":"Leer el título"},{"id":"i2","texto":"Ver qué variable va en cada eje y sus unidades"},{"id":"i3","texto":"Mirar la escala de los ejes"},{"id":"i4","texto":"Buscar la fuente de los datos"},{"id":"i5","texto":"Recién ahí, interpretar la forma"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Primero entender qué muestra; después, qué dice."}},{"slug":"ciencia-2.s1.p7","orden":7,"grupo":"ciencia-2.s1.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gráfico de barras sobre emisiones no dice las unidades. ¿Cuál es el problema?","opciones":[{"id":"o1","texto":"No se sabe si son totales o por persona"},{"id":"o2","texto":"Las barras quedan de un color menos lindo"},{"id":"o3","texto":"Ninguno: las barras hablan por sí solas"},{"id":"o4","texto":"Que el gráfico tiene que ser de torta"}]},"solucion":{"clave":["o1"],"explicacion":"Sin unidades, un gráfico puede comparar peras con manzanas sin que se note.","por_opcion":{"o3":"Sin unidades, el mismo dibujo puede significar cosas muy distintas."}}},{"slug":"ciencia-2.s1.p8","orden":8,"grupo":"ciencia-2.s1.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué tiene que tener un buen gráfico? Marcá todo.","opciones":[{"id":"o1","texto":"Un título claro"},{"id":"o2","texto":"Ejes con nombre y unidades"},{"id":"o3","texto":"La fuente de los datos"},{"id":"o4","texto":"Una escala que no distorsione"},{"id":"o5","texto":"Efectos en 3D para que se vea más moderno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los efectos 3D suelen deformar las proporciones. La claridad le gana al adorno."}},{"slug":"ciencia-2.s1.p9","orden":9,"grupo":"ciencia-2.s1.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Leer barras","cuerpo":["En un gráfico de barras, la longitud de la barra representa la cantidad. Por eso el eje de las barras tiene que empezar en cero: si empieza en otro número, la diferencia entre barras parece mucho mayor de lo que es."],"datos":{"tipo":"barras","titulo":"Consumo mensual de electricidad de cuatro casas","unidad":"kWh","filas":[{"etiqueta":"Casa A","valor":180},{"etiqueta":"Casa B","valor":240},{"etiqueta":"Casa C","valor":320},{"etiqueta":"Casa D","valor":150}],"nota":"Datos de ejemplo."}},"solucion":{}},{"slug":"ciencia-2.s1.p10","orden":10,"grupo":"ciencia-2.s1.p10","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según ese gráfico, ordená las casas por consumo, de más a menos.","items":[{"id":"i1","texto":"Casa C"},{"id":"i2","texto":"Casa B"},{"id":"i3","texto":"Casa A"},{"id":"i4","texto":"Casa D"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Barras que empiezan en cero: la longitud es proporcional a la cantidad.","valores":{"i1":"320 kWh","i2":"240 kWh","i3":"180 kWh","i4":"150 kWh"}}},{"slug":"ciencia-2.s1.p11","orden":11,"grupo":"ciencia-2.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En ese gráfico, una casa consume 320 kWh y otra 150 kWh. ¿Cuántas veces más consume la primera? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":2.1,"tolerancia":0.1,"explicacion":"320 ÷ 150 ≈ 2,1 veces. Si el eje empieza en cero, la barra más larga debería verse ese número de veces más larga."}},{"slug":"ciencia-2.s1.p11.v2","orden":11,"grupo":"ciencia-2.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En ese gráfico, una casa consume 240 kWh y otra 180 kWh. ¿Cuántas veces más consume la primera? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":1.3,"tolerancia":0.1,"explicacion":"240 ÷ 180 ≈ 1,3 veces. Si el eje empieza en cero, la barra más larga debería verse ese número de veces más larga."}},{"slug":"ciencia-2.s1.p11.v3","orden":11,"grupo":"ciencia-2.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En ese gráfico, una casa consume 180 kWh y otra 150 kWh. ¿Cuántas veces más consume la primera? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":1.2,"tolerancia":0.1,"explicacion":"180 ÷ 150 ≈ 1,2 veces. Si el eje empieza en cero, la barra más larga debería verse ese número de veces más larga."}},{"slug":"ciencia-2.s1.p12","orden":12,"grupo":"ciencia-2.s1.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción de un gráfico y marcá lo que falta o está mal.","segmentos":[{"id":"s1","texto":"Título: \"Emisiones de CO₂ de cinco países, 2023\"."},{"id":"s2","texto":"El eje vertical no tiene unidades."},{"id":"s3","texto":"La fuente es el Global Carbon Project."},{"id":"s4","texto":"El eje de las barras empieza en 400 para que se note la diferencia."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un gráfico honesto muestra unidades, fuente y un eje que no distorsiona.","por_opcion":{"s2":"Sin unidades no se sabe si son toneladas, millones de toneladas o toneladas por persona.","s4":"En barras, el eje tiene que empezar en cero; si no, exagera las diferencias."}}},{"slug":"ciencia-2.s1.p13","orden":13,"grupo":"ciencia-2.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para mostrar cambios en el tiempo se usa un gráfico de {{0}}; para comparar categorías, de {{1}}; y el eje de las barras tiene que empezar en {{2}}.","banco":[{"id":"w1","texto":"líneas"},{"id":"w2","texto":"barras"},{"id":"w3","texto":"cero"},{"id":"w4","texto":"torta"},{"id":"w5","texto":"puntos"},{"id":"w6","texto":"diez"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres reglas básicas para elegir y leer gráficos."}}]},{"slug":"ciencia-2.s2","orden":2,"tipo":"leccion","titulo_es":"Ver la tendencia entre el ruido","bajada_es":"Subidas y bajadas de corto plazo contra cambios de largo plazo: la curva del CO₂ y la diferencia entre tiempo y clima.","minutos":14,"pasos":[{"slug":"ciencia-2.s2.p1","orden":1,"grupo":"ciencia-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tendencia y variabilidad","cuerpo":["Muchos datos ambientales suben y bajan todo el tiempo: la temperatura de cada día, la lluvia de cada mes. Esa variación de corto plazo se llama variabilidad o \"ruido\". La tendencia es la dirección general a lo largo de muchos años.","Un día frío no dice nada sobre la tendencia del clima, igual que un mal día no dice nada del promedio de un año. Para ver una tendencia hacen falta muchos años de datos."]},"solucion":{}},{"slug":"ciencia-2.s2.p2","orden":2,"grupo":"ciencia-2.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La curva del CO₂","cuerpo":["Desde 1958 se mide el CO₂ del aire en el observatorio de Mauna Loa, en Hawái. La curva sube y baja cada año unos pocos ppm: baja en el verano del hemisferio norte, cuando los bosques del norte crecen y absorben CO₂, y sube en su invierno. Pero debajo de ese zigzag hay una tendencia clara: pasó de unas 315 ppm en 1958 a más de 420 ppm hoy."],"datos":{"tipo":"tabla","titulo":"CO₂ en Mauna Loa (promedio anual aproximado)","columnas":["Año","ppm"],"filas":[["1960","317"],["1980","339"],["2000","370"],["2020","414"],["2024","425"]],"nota":"Valores redondeados de la NOAA."}},"solucion":{}},{"slug":"ciencia-2.s2.p3","orden":3,"grupo":"ciencia-2.s2.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la curva del CO₂ de Mauna Loa sube y baja un poco cada año?","opciones":[{"id":"o1","texto":"Por la vegetación del norte en cada estación"},{"id":"o2","texto":"Porque los instrumentos fallan en invierno"},{"id":"o3","texto":"Porque las personas emiten menos CO₂ en verano"},{"id":"o4","texto":"Porque el volcán emite CO₂ solo algunos meses"}]},"solucion":{"clave":["o1"],"explicacion":"La vegetación del norte \"respira\" con las estaciones. La tendencia de fondo, en cambio, la marcan las emisiones.","por_opcion":{"o3":"Las emisiones cambian poco en el año; el zigzag viene de la vegetación."}}},{"slug":"ciencia-2.s2.p4","orden":4,"grupo":"ciencia-2.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la tabla, el CO₂ era de 317 ppm en 1960 y de 414 ppm en 2020. ¿Cuántas ppm por año subió en promedio en ese período? Redondeá a un decimal.","unidad":"ppm por año","decimales":1},"solucion":{"valor":1.6,"tolerancia":0.1,"explicacion":"(414 − 317) ÷ (2020 − 1960) = 97 ÷ 60 ≈ 1,6 ppm por año. Y el ritmo fue acelerándose con las décadas."}},{"slug":"ciencia-2.s2.p4.v2","orden":4,"grupo":"ciencia-2.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la tabla, el CO₂ era de 339 ppm en 1980 y de 414 ppm en 2020. ¿Cuántas ppm por año subió en promedio en ese período? Redondeá a un decimal.","unidad":"ppm por año","decimales":1},"solucion":{"valor":1.9,"tolerancia":0.1,"explicacion":"(414 − 339) ÷ (2020 − 1980) = 75 ÷ 40 ≈ 1,9 ppm por año. Y el ritmo fue acelerándose con las décadas."}},{"slug":"ciencia-2.s2.p4.v3","orden":4,"grupo":"ciencia-2.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la tabla, el CO₂ era de 370 ppm en 2000 y de 414 ppm en 2020. ¿Cuántas ppm por año subió en promedio en ese período? Redondeá a un decimal.","unidad":"ppm por año","decimales":1},"solucion":{"valor":2.2,"tolerancia":0.1,"explicacion":"(414 − 370) ÷ (2020 − 2000) = 44 ÷ 20 ≈ 2,2 ppm por año. Y el ritmo fue acelerándose con las décadas."}},{"slug":"ciencia-2.s2.p5","orden":5,"grupo":"ciencia-2.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si este invierno fue más frío que el anterior, el calentamiento global se detuvo.","razones":[{"id":"r1","texto":"Porque un año es variabilidad y la tendencia se mide en décadas"},{"id":"r2","texto":"Porque el calentamiento global solo ocurre en verano"},{"id":"r3","texto":"Porque un solo invierno define el clima"}]},"solucion":{"valor":false,"explicacion":"Un invierno es tiempo, no clima. La tendencia se mira en décadas: puede haber años fríos dentro de una tendencia de calentamiento.","clave":["r1"]}},{"slug":"ciencia-2.s2.p6","orden":6,"grupo":"ciencia-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tiempo y clima","cuerpo":["El tiempo es lo que pasa en la atmósfera en un lugar y un momento: la temperatura de hoy, la lluvia de esta semana. El clima es el promedio del tiempo durante muchos años, en general 30 o más.","Una forma de recordarlo: el tiempo es tu humor de hoy; el clima es tu personalidad."]},"solucion":{}},{"slug":"ciencia-2.s2.p7","orden":7,"grupo":"ciencia-2.s2.p7","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un dato de tiempo o de clima?","grupos":[{"id":"g1","nombre":"Tiempo"},{"id":"g2","nombre":"Clima"}],"items":[{"id":"i1","texto":"Mañana va a llover en Rosario"},{"id":"i2","texto":"Mendoza recibe en promedio unos 200 mm de lluvia por año"},{"id":"i3","texto":"Ayer hizo 38 °C en Santiago del Estero"},{"id":"i4","texto":"En los últimos 30 años aumentaron los días de calor extremo"},{"id":"i5","texto":"Esta semana hubo mucho viento"},{"id":"i6","texto":"El noreste es más húmedo que el oeste del país"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Clima son promedios y tendencias de muchos años. Tiempo, lo que pasa hoy."}},{"slug":"ciencia-2.s2.p8","orden":8,"grupo":"ciencia-2.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué elegir un período corto puede ocultar una tendencia.","items":[{"id":"i1","texto":"Se elige un período que empieza en un año muy caluroso"},{"id":"i2","texto":"Los años siguientes son algo más fríos por variabilidad"},{"id":"i3","texto":"En ese tramo corto parece que la temperatura baja"},{"id":"i4","texto":"Se oculta la tendencia de largo plazo, que es de calentamiento"},{"id":"i5","texto":"Los años calurosos hacen que la tendencia cambie de signo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Elegir el punto de partida a conveniencia es una trampa clásica. Por eso las tendencias se miran en décadas."}},{"slug":"ciencia-2.s2.p9","orden":9,"grupo":"ciencia-2.s2.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Promedios móviles","cuerpo":["Para ver mejor una tendencia se usan promedios móviles: en vez de graficar cada año, se grafica el promedio de, por ejemplo, 5 años alrededor de cada año. Así el zigzag se suaviza y la dirección general se ve mejor."]},"solucion":{}},{"slug":"ciencia-2.s2.p10","orden":10,"grupo":"ciencia-2.s2.p10","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Un promedio móvil de 3 años","planteo":"Temperaturas medias (°C) de cinco años seguidos: 16,1; 16,5; 16,0; 16,6; 16,8.","pasos":["Promedio de los años 1 a 3: (16,1 + 16,5 + 16,0) ÷ 3 = 16,2.","Promedio de los años 2 a 4: (16,5 + 16,0 + 16,6) ÷ 3 = 16,37.","Promedio de los años 3 a 5: (16,0 + 16,6 + 16,8) ÷ 3 = 16,47."],"resultado":"Los años sueltos suben y bajan; los promedios móviles suben de forma más pareja. Así se ve la tendencia."},"solucion":{}},{"slug":"ciencia-2.s2.p11","orden":11,"grupo":"ciencia-2.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de tres años con temperaturas medias de 16,5; 16; 16,6 °C. Redondeá a dos decimales.","unidad":"°C","decimales":2},"solucion":{"valor":16.37,"tolerancia":0.02,"explicacion":"(16,5 + 16 + 16,6) ÷ 3 ≈ 16,37 °C. Promediar varios años suaviza la variabilidad."}},{"slug":"ciencia-2.s2.p11.v2","orden":11,"grupo":"ciencia-2.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de tres años con temperaturas medias de 15,2; 15,8; 15,5 °C. Redondeá a dos decimales.","unidad":"°C","decimales":2},"solucion":{"valor":15.5,"tolerancia":0.02,"explicacion":"(15,2 + 15,8 + 15,5) ÷ 3 ≈ 15,5 °C. Promediar varios años suaviza la variabilidad."}},{"slug":"ciencia-2.s2.p11.v3","orden":11,"grupo":"ciencia-2.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de tres años con temperaturas medias de 18; 18,4; 18,2 °C. Redondeá a dos decimales.","unidad":"°C","decimales":2},"solucion":{"valor":18.2,"tolerancia":0.02,"explicacion":"(18 + 18,4 + 18,2) ÷ 3 ≈ 18,2 °C. Promediar varios años suaviza la variabilidad."}},{"slug":"ciencia-2.s2.p12","orden":12,"grupo":"ciencia-2.s2.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a ver una tendencia real en datos ambientales? Marcá todo.","opciones":[{"id":"o1","texto":"Mirar muchos años de datos"},{"id":"o2","texto":"Usar promedios móviles"},{"id":"o3","texto":"No elegir el punto de partida a conveniencia"},{"id":"o4","texto":"Comparar con la variabilidad normal"},{"id":"o5","texto":"Mirar solo el último mes"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un mes es ruido. Décadas, promedios y honestidad con el período muestran la tendencia."}},{"slug":"ciencia-2.s2.p13","orden":13,"grupo":"ciencia-2.s2.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gráfico muestra la lluvia de un año muy seco en una provincia. ¿Qué se puede concluir sobre su clima?","opciones":[{"id":"o1","texto":"Poco: hacen falta muchos años para ver una tendencia"},{"id":"o2","texto":"Que la provincia se está convirtiendo en un desierto"},{"id":"o3","texto":"Que el cambio climático no existe en esa provincia"},{"id":"o4","texto":"Que el año siguiente también va a ser seco"}]},"solucion":{"clave":["o1"],"explicacion":"Un año es tiempo acumulado, no clima. El clima se lee en décadas.","por_opcion":{"o3":"Un año no alcanza para concluir nada sobre el clima, ni a favor ni en contra."}}},{"slug":"ciencia-2.s2.p14","orden":14,"grupo":"ciencia-2.s2.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su significado.","izquierda":[{"id":"a1","texto":"Variabilidad"},{"id":"a2","texto":"Tendencia"},{"id":"a3","texto":"Promedio móvil"},{"id":"a4","texto":"Clima"}],"derecha":[{"id":"b1","texto":"Subidas y bajadas de corto plazo"},{"id":"b2","texto":"Dirección general a lo largo de muchos años"},{"id":"b3","texto":"Promedio de varios años alrededor de cada año"},{"id":"b4","texto":"Promedio del tiempo durante 30 años o más"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro términos para leer cualquier serie de datos ambientales."}},{"slug":"ciencia-2.s2.p15","orden":15,"grupo":"ciencia-2.s2.p15","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este tuit y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El CO₂ en Mauna Loa pasó de unas 315 ppm en 1958 a más de 420 ppm hoy."},{"id":"s2","texto":"Esta semana hizo frío: el calentamiento global es un invento."},{"id":"s3","texto":"La curva del CO₂ sube y baja cada año por la vegetación."},{"id":"s4","texto":"Si tomo solo de 2016 a 2018, la temperatura bajó, así que no hay calentamiento."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Tiempo contra clima, y tramos elegidos a conveniencia: las dos trampas más comunes.","por_opcion":{"s2":"Una semana es tiempo, no clima. La tendencia se mide en décadas.","s4":"Elegir un tramo corto que empieza en un año muy caluroso oculta la tendencia."}}},{"slug":"ciencia-2.s2.p16","orden":16,"grupo":"ciencia-2.s2.p16","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El {{0}} es lo que pasa hoy; el {{1}} es el promedio de muchos años; y para ver una tendencia se usan promedios {{2}}.","banco":[{"id":"w1","texto":"tiempo"},{"id":"w2","texto":"clima"},{"id":"w3","texto":"móviles"},{"id":"w4","texto":"viento"},{"id":"w5","texto":"pronóstico"},{"id":"w6","texto":"fijos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La diferencia clave para leer cualquier dato del clima."}}]},{"slug":"ciencia-2.s3","orden":3,"tipo":"leccion","titulo_es":"Gráficos que engañan","bajada_es":"Ejes recortados, escalas dobles, tramos elegidos y dibujos en 3D: cómo un gráfico puede decir algo que los datos no dicen.","minutos":11,"pasos":[{"slug":"ciencia-2.s3.p1","orden":1,"grupo":"ciencia-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El eje recortado","cuerpo":["Si el eje vertical de un gráfico de barras empieza en un número alto en vez de en cero, diferencias chicas parecen enormes. Una barra de 102 y otra de 100 pueden verse una el doble que la otra si el eje empieza en 98.","En los gráficos de líneas no siempre es obligatorio empezar en cero, pero hay que mirar la escala para no exagerar ni esconder un cambio."]},"solucion":{}},{"slug":"ciencia-2.s3.p2","orden":2,"grupo":"ciencia-2.s3.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El mismo dato, dos impresiones","planteo":"Un municipio reciclaba 20 toneladas por mes y pasó a 22.","pasos":["Con el eje desde 0: la barra de 22 es apenas un 10 % más alta que la de 20.","Con el eje desde 19: la barra de 20 mide 1 unidad y la de 22 mide 3: parece el triple."],"resultado":"El dato es el mismo: 10 % más. El eje recortado hace que parezca un triunfo enorme."},"solucion":{}},{"slug":"ciencia-2.s3.p3","orden":3,"grupo":"ciencia-2.s3.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos barras valen 20 y 22. Si el eje empieza en 19, ¿cuántas veces más alta se ve la barra de 22 que la de 20? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"Se ven 3 contra 1: 3 veces. En realidad, 22 es solo 10 % más que 20."}},{"slug":"ciencia-2.s3.p3.v2","orden":3,"grupo":"ciencia-2.s3.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos barras valen 100 y 105. Si el eje empieza en 98, ¿cuántas veces más alta se ve la barra de 105 que la de 100? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.5,"tolerancia":0.1,"explicacion":"Se ven 7 contra 2: 3,5 veces. En realidad, 105 es solo 5 % más que 100."}},{"slug":"ciencia-2.s3.p3.v3","orden":3,"grupo":"ciencia-2.s3.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos barras valen 50 y 55. Si el eje empieza en 48, ¿cuántas veces más alta se ve la barra de 55 que la de 50? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.5,"tolerancia":0.1,"explicacion":"Se ven 7 contra 2: 3,5 veces. En realidad, 55 es solo 10 % más que 50."}},{"slug":"ciencia-2.s3.p4","orden":4,"grupo":"ciencia-2.s3.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el eje de un gráfico de barras empieza en un número alto, las diferencias parecen más grandes de lo que son.","razones":[{"id":"r1","texto":"Porque se pierde la proporción entre las barras"},{"id":"r2","texto":"Porque las barras se vuelven más finas"},{"id":"r3","texto":"Porque el eje recortado achica las diferencias"}]},"solucion":{"valor":true,"explicacion":"Las barras recortadas pierden la proporción: diferencias chicas parecen enormes. En barras, el eje debe empezar en cero.","clave":["r1"]}},{"slug":"ciencia-2.s3.p5","orden":5,"grupo":"ciencia-2.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Otras trampas","cuerpo":["Hay otros recursos que distorsionan: usar dos ejes verticales con escalas distintas para que dos líneas parezcan moverse juntas; elegir solo el tramo de años que conviene; comparar totales de países con poblaciones muy distintas sin pasar a \"por persona\"; usar íconos o dibujos en 3D donde el área crece mucho más que el valor; y no mostrar la fuente."]},"solucion":{}},{"slug":"ciencia-2.s3.p6","orden":6,"grupo":"ciencia-2.s3.p6","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada trampa con su efecto.","izquierda":[{"id":"a1","texto":"Eje de barras que no empieza en cero"},{"id":"a2","texto":"Dos ejes con escalas distintas"},{"id":"a3","texto":"Tramo de años elegido a conveniencia"},{"id":"a4","texto":"Íconos que crecen en alto y en ancho"}],"derecha":[{"id":"b1","texto":"Exagera diferencias chicas"},{"id":"b2","texto":"Hace parecer relacionadas dos cosas"},{"id":"b3","texto":"Oculta la tendencia de largo plazo"},{"id":"b4","texto":"El área crece mucho más que el valor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro trampas frecuentes. Reconocerlas es la mejor defensa."}},{"slug":"ciencia-2.s3.p7","orden":7,"grupo":"ciencia-2.s3.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un ícono que duplica su altura engaña.","items":[{"id":"i1","texto":"Un valor se duplica"},{"id":"i2","texto":"El dibujo se agranda al doble de alto y al doble de ancho"},{"id":"i3","texto":"Su área queda cuatro veces más grande"},{"id":"i4","texto":"El ojo percibe que el valor se cuadruplicó"},{"id":"i5","texto":"El ojo solo mira la altura de los dibujos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Por eso los gráficos con dibujos agrandados exageran los cambios."}},{"slug":"ciencia-2.s3.p8","orden":8,"grupo":"ciencia-2.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una práctica honesta o engañosa?","grupos":[{"id":"g1","nombre":"Honesta"},{"id":"g2","nombre":"Engañosa"}],"items":[{"id":"i1","texto":"Mostrar la serie completa de años disponibles"},{"id":"i2","texto":"Recortar el eje de un gráfico de barras"},{"id":"i3","texto":"Aclarar si los valores son totales o por persona"},{"id":"i4","texto":"Mostrar solo los años que confirman la idea"},{"id":"i5","texto":"Citar la fuente de los datos"},{"id":"i6","texto":"Usar dibujos en 3D que deforman las proporciones"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La honestidad en un gráfico es mostrar todo lo necesario para interpretarlo bien."}},{"slug":"ciencia-2.s3.p9","orden":9,"grupo":"ciencia-2.s3.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gráfico compara las emisiones totales de Argentina y de Uruguay y concluye que Argentina contamina mucho más. ¿Qué falta?","opciones":[{"id":"o1","texto":"Comparar por persona, porque las poblaciones son muy distintas"},{"id":"o2","texto":"Ponerle colores más fuertes al gráfico"},{"id":"o3","texto":"Nada: el total es la única forma válida de comparar"},{"id":"o4","texto":"Comparar con el año en que Uruguay ganó un Mundial"}]},"solucion":{"clave":["o1"],"explicacion":"Argentina tiene más de diez veces la población de Uruguay. El total y el \"por persona\" responden preguntas distintas.","por_opcion":{"o3":"El total es útil, pero con poblaciones tan distintas, el dato por persona cambia la lectura."}}},{"slug":"ciencia-2.s3.p10","orden":10,"grupo":"ciencia-2.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas conviene hacerle a un gráfico sospechoso? Marcá todas.","opciones":[{"id":"o1","texto":"¿Dónde empieza el eje?"},{"id":"o2","texto":"¿De qué período son los datos y por qué ese?"},{"id":"o3","texto":"¿Son totales o por persona?"},{"id":"o4","texto":"¿Cuál es la fuente?"},{"id":"o5","texto":"¿Qué tan moderno es el diseño?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro preguntas que desarman la mayoría de los gráficos engañosos."}},{"slug":"ciencia-2.s3.p11","orden":11,"grupo":"ciencia-2.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción de un afiche y marcá lo que es engañoso.","segmentos":[{"id":"s1","texto":"Muestra el reciclaje de la ciudad de 2015 a 2024."},{"id":"s2","texto":"El eje de las barras empieza en 18 toneladas."},{"id":"s3","texto":"Cita como fuente al área de ambiente del municipio."},{"id":"s4","texto":"Las bolsas dibujadas crecen en alto y en ancho según el valor."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El dato puede ser real y el dibujo, engañoso.","por_opcion":{"s2":"Así, pasar de 20 a 22 parece triplicarse.","s4":"El área crece mucho más que el valor y exagera el cambio."}}},{"slug":"ciencia-2.s3.p12","orden":12,"grupo":"ciencia-2.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un gráfico de barras el eje tiene que empezar en {{0}}; comparar países sin pasar a \"por {{1}}\" puede engañar; y elegir solo algunos {{2}} oculta la tendencia.","banco":[{"id":"w1","texto":"cero"},{"id":"w2","texto":"persona"},{"id":"w3","texto":"años"},{"id":"w4","texto":"cien"},{"id":"w5","texto":"kilómetro"},{"id":"w6","texto":"colores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres trampas para detectar en cualquier gráfico."}},{"slug":"ciencia-2.s3.p13","orden":13,"grupo":"ciencia-2.s3.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos cambios reales de menor a mayor, aunque un gráfico recortado los muestre distinto.","items":[{"id":"i1","texto":"De 100 a 102"},{"id":"i2","texto":"De 20 a 22"},{"id":"i3","texto":"De 50 a 60"},{"id":"i4","texto":"De 10 a 15"}],"extremos":["Menor cambio","Mayor cambio"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Calcular el cambio porcentual es la mejor forma de no depender del dibujo.","valores":{"i1":"+2 %","i2":"+10 %","i3":"+20 %","i4":"+50 %"}}}]},{"slug":"ciencia-2.s4","orden":4,"tipo":"leccion","titulo_es":"Promedio, mediana y extremos","bajada_es":"Cuándo el promedio engaña, qué es la mediana y por qué los valores extremos importan.","minutos":11,"pasos":[{"slug":"ciencia-2.s4.p1","orden":1,"grupo":"ciencia-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Promedio y mediana","cuerpo":["El promedio (o media) se calcula sumando todos los valores y dividiendo por la cantidad. La mediana es el valor del medio cuando se ordenan los datos de menor a mayor: la mitad está por debajo y la mitad por encima.","Si hay valores muy extremos, el promedio se mueve mucho y deja de representar a la mayoría. La mediana, en cambio, casi no cambia."]},"solucion":{}},{"slug":"ciencia-2.s4.p2","orden":2,"grupo":"ciencia-2.s4.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El consumo de agua de una cuadra","planteo":"Diez casas usan por día (litros): 300, 320, 350, 360, 380, 400, 420, 450, 480 y 5.000 (una casa con pileta y pérdida).","pasos":["Promedio: la suma es 8.460; ÷ 10 = 846 litros.","Mediana: ordenadas, las del medio son 380 y 400: (380 + 400) ÷ 2 = 390 litros."],"resultado":"El promedio (846) no representa a ninguna casa real: lo infla una sola. La mediana (390) describe mejor a la casa típica."},"solucion":{}},{"slug":"ciencia-2.s4.p3","orden":3,"grupo":"ciencia-2.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de estos datos: 3, 5, 7, 9, 41.","unidad":"","decimales":1},"solucion":{"valor":13,"tolerancia":0.26,"explicacion":"(3 + 5 + 7 + 9 + 41) ÷ 5 = 13. Un solo valor alto (41) tira el promedio muy arriba de la mayoría."}},{"slug":"ciencia-2.s4.p3.v2","orden":3,"grupo":"ciencia-2.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de estos datos: 10, 12, 14, 16, 98.","unidad":"","decimales":1},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"(10 + 12 + 14 + 16 + 98) ÷ 5 = 30. Un solo valor alto (98) tira el promedio muy arriba de la mayoría."}},{"slug":"ciencia-2.s4.p3.v3","orden":3,"grupo":"ciencia-2.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de estos datos: 2, 4, 4, 6, 24.","unidad":"","decimales":1},"solucion":{"valor":8,"tolerancia":0.16,"explicacion":"(2 + 4 + 4 + 6 + 24) ÷ 5 = 8. Un solo valor alto (24) tira el promedio muy arriba de la mayoría."}},{"slug":"ciencia-2.s4.p4","orden":4,"grupo":"ciencia-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuál es la mediana de estos datos: 3, 5, 7, 9, 41?","unidad":"","decimales":0},"solucion":{"valor":7,"tolerancia":0.5,"explicacion":"Ordenados, el del medio es 7. La mediana no se deja arrastrar por el valor extremo (41)."}},{"slug":"ciencia-2.s4.p4.v2","orden":4,"grupo":"ciencia-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuál es la mediana de estos datos: 10, 12, 14, 16, 98?","unidad":"","decimales":0},"solucion":{"valor":14,"tolerancia":0.5,"explicacion":"Ordenados, el del medio es 14. La mediana no se deja arrastrar por el valor extremo (98)."}},{"slug":"ciencia-2.s4.p4.v3","orden":4,"grupo":"ciencia-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuál es la mediana de estos datos: 2, 4, 4, 6, 24?","unidad":"","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"Ordenados, el del medio es 4. La mediana no se deja arrastrar por el valor extremo (24)."}},{"slug":"ciencia-2.s4.p5","orden":5,"grupo":"ciencia-2.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El promedio siempre describe bien al caso típico.","razones":[{"id":"r1","texto":"Porque los valores extremos lo arrastran"},{"id":"r2","texto":"Porque el promedio nunca cambia"},{"id":"r3","texto":"Porque la mediana y el promedio son siempre iguales"}]},"solucion":{"valor":false,"explicacion":"Si hay valores extremos, el promedio puede quedar lejos de casi todos los casos. Por eso, con datos muy desparejos, se usa la mediana.","clave":["r1"]}},{"slug":"ciencia-2.s4.p6","orden":6,"grupo":"ciencia-2.s4.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Conviene usar el promedio o la mediana?","grupos":[{"id":"g1","nombre":"Mediana"},{"id":"g2","nombre":"Promedio"}],"items":[{"id":"i1","texto":"Ingresos de las familias de un país"},{"id":"i2","texto":"Temperatura media de un mes"},{"id":"i3","texto":"Consumo de agua de una cuadra con una casa que tiene pileta"},{"id":"i4","texto":"Altura de plantas de un experimento sin valores raros"},{"id":"i5","texto":"Precio de las casas de un barrio con algunas mansiones"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Con datos desparejos, la mediana. Con datos parejos, el promedio funciona bien y usa toda la información."}},{"slug":"ciencia-2.s4.p7","orden":7,"grupo":"ciencia-2.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los extremos importan","cuerpo":["A veces lo más importante no es el valor típico sino los extremos. En el clima, un aumento chico del promedio de temperatura puede significar muchos más días de calor extremo. En la contaminación del aire, un promedio aceptable puede esconder días peligrosos.","Por eso, además del promedio o la mediana, conviene mirar el rango (del mínimo al máximo) y cuántas veces se supera un umbral."]},"solucion":{}},{"slug":"ciencia-2.s4.p8","orden":8,"grupo":"ciencia-2.s4.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un aumento chico del promedio multiplica los días extremos.","items":[{"id":"i1","texto":"La temperatura promedio de un lugar sube 1 °C"},{"id":"i2","texto":"Toda la distribución de días se corre hacia arriba"},{"id":"i3","texto":"Días que antes eran apenas calurosos pasan a ser extremos"},{"id":"i4","texto":"Los días de calor extremo se vuelven mucho más frecuentes"},{"id":"i5","texto":"Si sube el promedio, desaparecen los días fríos para siempre"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un corrimiento chico del centro cambia mucho las colas. Por eso 1 °C más importa tanto."}},{"slug":"ciencia-2.s4.p9","orden":9,"grupo":"ciencia-2.s4.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos conviene informar para describir bien la calidad del aire de un año? Marcá todos.","opciones":[{"id":"o1","texto":"El promedio anual"},{"id":"o2","texto":"La cantidad de días que se superó el valor guía"},{"id":"o3","texto":"El valor máximo"},{"id":"o4","texto":"En qué condiciones ocurrieron los picos"},{"id":"o5","texto":"Solo el dato del día más limpio"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un solo número no alcanza. El típico y los extremos cuentan historias distintas."}},{"slug":"ciencia-2.s4.p10","orden":10,"grupo":"ciencia-2.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El PM2,5 de siete días fue: 12, 18, 25, 9, 30, 14, 20 µg/m³. ¿Cuántos días superó el valor guía diario de 15 µg/m³?","unidad":"días","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"Superan 15: 18, 25, 30, 20. Son 4 días de 7. Contar superaciones dice más que un promedio."}},{"slug":"ciencia-2.s4.p10.v2","orden":10,"grupo":"ciencia-2.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El PM2,5 de siete días fue: 8, 16, 22, 17, 11, 19, 26 µg/m³. ¿Cuántos días superó el valor guía diario de 15 µg/m³?","unidad":"días","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"Superan 15: 16, 22, 17, 19, 26. Son 5 días de 7. Contar superaciones dice más que un promedio."}},{"slug":"ciencia-2.s4.p10.v3","orden":10,"grupo":"ciencia-2.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El PM2,5 de siete días fue: 5, 7, 18, 20, 9, 3, 16 µg/m³. ¿Cuántos días superó el valor guía diario de 15 µg/m³?","unidad":"días","decimales":0},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"Superan 15: 18, 20, 16. Son 3 días de 7. Contar superaciones dice más que un promedio."}},{"slug":"ciencia-2.s4.p11","orden":11,"grupo":"ciencia-2.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un barrio, casi todas las casas usan entre 300 y 450 litros por día y dos usan más de 4.000. ¿Qué número describe mejor a la casa típica?","opciones":[{"id":"o1","texto":"La mediana"},{"id":"o2","texto":"El promedio"},{"id":"o3","texto":"El valor máximo"},{"id":"o4","texto":"La suma de todas las casas"}]},"solucion":{"clave":["o1"],"explicacion":"Con dos valores extremos, la mediana representa mejor a la mayoría.","por_opcion":{"o3":"El máximo describe a la casa que más usa, no a la típica."}}},{"slug":"ciencia-2.s4.p12","orden":12,"grupo":"ciencia-2.s4.p12","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Para encontrar la mediana, ordená estos consumos diarios (litros) de menor a mayor.","items":[{"id":"i1","texto":"300"},{"id":"i2","texto":"380"},{"id":"i3","texto":"420"},{"id":"i4","texto":"480"},{"id":"i5","texto":"5.000"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Ordenados, el del medio es 420: esa es la mediana. El promedio, en cambio, sería 1.316, arrastrado por la casa de 5.000."}},{"slug":"ciencia-2.s4.p13","orden":13,"grupo":"ciencia-2.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"La mediana del consumo de agua de la cuadra es 390 litros."},{"id":"s2","texto":"El promedio de 846 litros muestra que cada casa usa 846 litros."},{"id":"s3","texto":"Una casa usa 5.000 litros por día."},{"id":"s4","texto":"Como el promedio anual de PM2,5 es aceptable, nunca hubo días malos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Promedio, mediana y extremos: tres miradas que se complementan.","por_opcion":{"s2":"Una sola casa con pileta y pérdida infla el promedio: ninguna casa típica usa eso.","s4":"El promedio puede esconder picos: hay que contar los días que superan el valor guía."}}},{"slug":"ciencia-2.s4.p14","orden":14,"grupo":"ciencia-2.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La {{0}} es el valor del medio; el {{1}} se deja arrastrar por los extremos; y a veces importa contar cuántas veces se supera un {{2}}.","banco":[{"id":"w1","texto":"mediana"},{"id":"w2","texto":"promedio"},{"id":"w3","texto":"umbral"},{"id":"w4","texto":"moda"},{"id":"w5","texto":"rango"},{"id":"w6","texto":"color"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para describir datos sin engañar."}}]},{"slug":"ciencia-2.s5","orden":5,"tipo":"leccion","titulo_es":"Porcentajes, puntos y tasas","bajada_es":"El doble de un riesgo mínimo, puntos porcentuales y datos por persona: las trampas de los números relativos.","minutos":11,"pasos":[{"slug":"ciencia-2.s5.p1","orden":1,"grupo":"ciencia-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Porcentaje y puntos porcentuales","cuerpo":["Si el reciclaje de una ciudad pasa del 10 % al 15 %, subió 5 puntos porcentuales, pero en términos relativos subió un 50 % (porque 5 es la mitad de 10). Las dos frases son ciertas, pero suenan muy distintas.","Los puntos porcentuales miden la diferencia entre dos porcentajes; el cambio porcentual mide cuánto cambió respecto del valor inicial."]},"solucion":{}},{"slug":"ciencia-2.s5.p2","orden":2,"grupo":"ciencia-2.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El reciclaje de una ciudad pasó del 10 % al 15 %. ¿En cuántos puntos porcentuales subió?","unidad":"puntos porcentuales","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"15 − 10 = 5 puntos porcentuales. En términos relativos, subió un 50 %."}},{"slug":"ciencia-2.s5.p2.v2","orden":2,"grupo":"ciencia-2.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El reciclaje de una ciudad pasó del 20 % al 25 %. ¿En cuántos puntos porcentuales subió?","unidad":"puntos porcentuales","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"25 − 20 = 5 puntos porcentuales. En términos relativos, subió un 25 %."}},{"slug":"ciencia-2.s5.p2.v3","orden":2,"grupo":"ciencia-2.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El reciclaje de una ciudad pasó del 4 % al 6 %. ¿En cuántos puntos porcentuales subió?","unidad":"puntos porcentuales","decimales":0},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"6 − 4 = 2 puntos porcentuales. En términos relativos, subió un 50 %."}},{"slug":"ciencia-2.s5.p3","orden":3,"grupo":"ciencia-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el reciclaje pasó del 10 % al 15 %, ¿en qué porcentaje aumentó respecto del valor inicial?","unidad":"%","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(15 − 10) ÷ 10 × 100 = 50 %. Mismo cambio, contado de otra forma: 5 puntos o 50 % más."}},{"slug":"ciencia-2.s5.p3.v2","orden":3,"grupo":"ciencia-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el reciclaje pasó del 20 % al 25 %, ¿en qué porcentaje aumentó respecto del valor inicial?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"(25 − 20) ÷ 20 × 100 = 25 %. Mismo cambio, contado de otra forma: 5 puntos o 25 % más."}},{"slug":"ciencia-2.s5.p3.v3","orden":3,"grupo":"ciencia-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el reciclaje pasó del 4 % al 6 %, ¿en qué porcentaje aumentó respecto del valor inicial?","unidad":"%","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(6 − 4) ÷ 4 × 100 = 50 %. Mismo cambio, contado de otra forma: 2 puntos o 50 % más."}},{"slug":"ciencia-2.s5.p4","orden":4,"grupo":"ciencia-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Riesgo relativo y absoluto","cuerpo":["Un titular dice: \"tal cosa duplica el riesgo de una enfermedad\". Suena alarmante, pero depende del riesgo de partida. Si el riesgo pasa de 1 en 100.000 a 2 en 100.000, se duplicó (riesgo relativo), pero el aumento real es de 1 caso cada 100.000 personas (riesgo absoluto).","Para entender un riesgo hacen falta los dos números: cuánto cambia y desde dónde."]},"solucion":{}},{"slug":"ciencia-2.s5.p5","orden":5,"grupo":"ciencia-2.s5.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"\"Un producto duplica el riesgo de una enfermedad que afecta a 1 de cada 100.000 personas.\" ¿Qué significa en números absolutos?","opciones":[{"id":"o1","texto":"Pasa de 1 a 2 casos cada 100.000 personas"},{"id":"o2","texto":"La mitad de las personas se va a enfermar"},{"id":"o3","texto":"Pasa de 1 a 200.000 casos"},{"id":"o4","texto":"El 2 % de las personas se va a enfermar"}]},"solucion":{"clave":["o1"],"explicacion":"El riesgo relativo impresiona; el absoluto dimensiona. Los dos juntos informan.","por_opcion":{"o3":"Duplicar 1 es 2: el aumento absoluto es muy chico."}}},{"slug":"ciencia-2.s5.p6","orden":6,"grupo":"ciencia-2.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un riesgo se duplica, siempre es un riesgo grande.","razones":[{"id":"r1","texto":"Porque depende de cuál era el riesgo de partida"},{"id":"r2","texto":"Porque duplicar un riesgo lo hace del 100 %"},{"id":"r3","texto":"Porque los riesgos nunca se duplican"}]},"solucion":{"valor":false,"explicacion":"Depende del valor inicial. Duplicar un riesgo mínimo sigue siendo un riesgo chico en términos absolutos; duplicar uno alto es grave.","clave":["r1"]}},{"slug":"ciencia-2.s5.p7","orden":7,"grupo":"ciencia-2.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por persona","cuerpo":["Comparar totales entre lugares de distinto tamaño engaña. China emite mucho más CO₂ total que Argentina, pero por persona la comparación cambia; y países chicos con mucho consumo pueden tener emisiones por persona muy altas aunque sus totales sean chicos.","Las tasas por persona, por habitante o por cada 100.000 habitantes permiten comparar lugares de tamaños distintos. Los totales responden cuánto aporta cada lugar al problema global. Las dos miradas son útiles, para preguntas distintas."]},"solucion":{}},{"slug":"ciencia-2.s5.p8","orden":8,"grupo":"ciencia-2.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 180 millones de toneladas de CO₂ por año y tiene 45 millones de habitantes. ¿Cuántas toneladas por persona emite? Redondeá a un decimal.","unidad":"t por persona","decimales":1},"solucion":{"valor":4,"tolerancia":0.1,"explicacion":"180 ÷ 45 ≈ 4 t por persona. El total y el \"por persona\" responden preguntas distintas."}},{"slug":"ciencia-2.s5.p8.v2","orden":8,"grupo":"ciencia-2.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 12 millones de toneladas de CO₂ por año y tiene 3,5 millones de habitantes. ¿Cuántas toneladas por persona emite? Redondeá a un decimal.","unidad":"t por persona","decimales":1},"solucion":{"valor":3.4,"tolerancia":0.1,"explicacion":"12 ÷ 3,5 ≈ 3,4 t por persona. El total y el \"por persona\" responden preguntas distintas."}},{"slug":"ciencia-2.s5.p8.v3","orden":8,"grupo":"ciencia-2.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 5.000 millones de toneladas de CO₂ por año y tiene 1.400 millones de habitantes. ¿Cuántas toneladas por persona emite? Redondeá a un decimal.","unidad":"t por persona","decimales":1},"solucion":{"valor":3.6,"tolerancia":0.1,"explicacion":"5.000 ÷ 1.400 ≈ 3,6 t por persona. El total y el \"por persona\" responden preguntas distintas."}},{"slug":"ciencia-2.s5.p9","orden":9,"grupo":"ciencia-2.s5.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Para esta pregunta conviene el total o el dato por persona?","grupos":[{"id":"g1","nombre":"Total"},{"id":"g2","nombre":"Por persona"}],"items":[{"id":"i1","texto":"¿Qué países aportan más al calentamiento global?"},{"id":"i2","texto":"¿En qué país se consume más energía por habitante?"},{"id":"i3","texto":"¿Cuánta basura tiene que procesar el relleno de la ciudad?"},{"id":"i4","texto":"¿Qué ciudad genera más basura por vecino?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Cada pregunta tiene su número. El error es usar uno para la pregunta del otro."}},{"slug":"ciencia-2.s5.p10","orden":10,"grupo":"ciencia-2.s5.p10","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada frase con lo que realmente mide.","izquierda":[{"id":"a1","texto":"Subió 5 puntos porcentuales"},{"id":"a2","texto":"Subió un 50 %"},{"id":"a3","texto":"Duplica el riesgo"},{"id":"a4","texto":"2 casos cada 100.000"}],"derecha":[{"id":"b1","texto":"La diferencia entre dos porcentajes"},{"id":"b2","texto":"El cambio respecto del valor inicial"},{"id":"b3","texto":"El riesgo relativo"},{"id":"b4","texto":"El riesgo absoluto"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro formas de hablar de cambios. Confundirlas es muy fácil y muy común."}},{"slug":"ciencia-2.s5.p11","orden":11,"grupo":"ciencia-2.s5.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene preguntar ante un titular con porcentajes? Marcá todo.","opciones":[{"id":"o1","texto":"¿Es un cambio en puntos o en porcentaje?"},{"id":"o2","texto":"¿Cuál era el valor de partida?"},{"id":"o3","texto":"¿Es un total o un dato por persona?"},{"id":"o4","texto":"¿Cuál es el riesgo absoluto?"},{"id":"o5","texto":"¿Cuántas veces se compartió la nota?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro preguntas para no dejarse llevar por un número suelto."}},{"slug":"ciencia-2.s5.p12","orden":12,"grupo":"ciencia-2.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"El reciclaje pasó del 10 % al 12 % de los residuos."},{"id":"s2","texto":"Es decir, el reciclaje subió 20 puntos porcentuales."},{"id":"s3","texto":"La ciudad tiene 500.000 habitantes."},{"id":"s4","texto":"Como la ciudad vecina recicla más toneladas, recicla mejor por vecino."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Puntos contra porcentaje y total contra por persona: las dos confusiones más frecuentes.","por_opcion":{"s2":"Subió 2 puntos porcentuales; en términos relativos, un 20 %.","s4":"Si tiene más habitantes, más toneladas no significa más por vecino."}}},{"slug":"ciencia-2.s5.p13","orden":13,"grupo":"ciencia-2.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Pasar del 10 % al 15 % es subir 5 puntos {{0}}; duplicar un riesgo es un cambio {{1}}; y para comparar países de distinto tamaño se usan datos por {{2}}.","banco":[{"id":"w1","texto":"porcentuales"},{"id":"w2","texto":"relativo"},{"id":"w3","texto":"persona"},{"id":"w4","texto":"decimales"},{"id":"w5","texto":"absoluto"},{"id":"w6","texto":"kilómetro"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para leer números relativos."}}]},{"slug":"ciencia-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: leer gráficos y datos","bajada_es":"Tipos de gráficos, tendencias, trampas, promedios y porcentajes, mezclados.","minutos":8,"pasos":[{"slug":"ciencia-2.s6.p1","orden":1,"grupo":"ciencia-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Leer gráficos y datos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"ciencia-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el gráfico del concejal","bajada_es":"Un concejal presenta un gráfico para mostrar un éxito ambiental. Revisalo con todo lo que aprendiste.","minutos":10,"pasos":[{"slug":"ciencia-2.s7.p1","orden":1,"grupo":"ciencia-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El gráfico","cuerpo":["El concejal muestra un gráfico de barras titulado \"¡Triplicamos el reciclaje!\". Las barras muestran 20 toneladas por mes en 2023 y 22 toneladas por mes en 2024. El eje vertical empieza en 19. No dice la fuente.","Según datos del municipio, la ciudad genera unas 400 toneladas de residuos por mes, y la población creció de 100.000 a 104.000 habitantes entre esos años."]},"solucion":{}},{"slug":"ciencia-2.s7.p2","orden":2,"grupo":"ciencia-2.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En qué porcentaje aumentó realmente el reciclaje, de 20 a 22 toneladas por mes?","unidad":"%","decimales":0,"contexto":"Reciclaje: 20 t/mes en 2023, 22 t/mes en 2024."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"(22 − 20) ÷ 20 × 100 = 10 %. No se triplicó: aumentó un 10 %."}},{"slug":"ciencia-2.s7.p3","orden":3,"grupo":"ciencia-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de los residuos de la ciudad se recicla en 2024? (22 de 400 toneladas por mes)","unidad":"%","decimales":1,"contexto":"La ciudad genera 400 t/mes; recicla 22 t/mes."},"solucion":{"valor":5.5,"tolerancia":0.11,"explicacion":"22 ÷ 400 × 100 = 5,5 %. El 94,5 % sigue yendo a disposición final."}},{"slug":"ciencia-2.s7.p4","orden":4,"grupo":"ciencia-2.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 22 toneladas por mes y 104.000 habitantes, ¿cuántos kilos por habitante por mes se reciclan? Redondeá a dos decimales.","unidad":"kg por habitante","decimales":2},"solucion":{"valor":0.21,"tolerancia":0.01,"explicacion":"22 t = 22.000 kg; ÷ 104.000 ≈ 0,21 kg por habitante por mes. En 2023, con 100.000 habitantes y 20 t, eran 0,2 kg: la mejora por persona es todavía menor."}},{"slug":"ciencia-2.s7.p5","orden":5,"grupo":"ciencia-2.s7.p5","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas tiene el gráfico del concejal? Marcá todos.","opciones":[{"id":"o1","texto":"El eje de las barras empieza en 19, no en cero"},{"id":"o2","texto":"El título dice \"triplicamos\" cuando el aumento fue del 10 %"},{"id":"o3","texto":"No cita la fuente"},{"id":"o4","texto":"No aclara qué parte del total de residuos representa"},{"id":"o5","texto":"Usa barras para comparar dos años"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Comparar dos años con barras está bien. Lo engañoso es el eje recortado, el título y la falta de contexto."}},{"slug":"ciencia-2.s7.p6","orden":6,"grupo":"ciencia-2.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál sería un título honesto para el gráfico?","opciones":[{"id":"o1","texto":"El reciclaje subió un 10 %, a 22 toneladas por mes"},{"id":"o2","texto":"¡Triplicamos el reciclaje de la ciudad en un año!"},{"id":"o3","texto":"La ciudad ya recicla casi todo"},{"id":"o4","texto":"Somos la ciudad que más recicla del país"}]},"solucion":{"clave":["o1"],"explicacion":"Un título honesto dice el cambio real, con su magnitud.","por_opcion":{"o3":"Recicla el 5,5 % de sus residuos: está muy lejos de casi todo."}}},{"slug":"ciencia-2.s7.p7","orden":7,"grupo":"ciencia-2.s7.p7","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas formas de presentar el dato de la más honesta a la más engañosa.","items":[{"id":"i1","texto":"Barras desde cero, con fuente y el porcentaje del total"},{"id":"i2","texto":"Barras desde cero, sin fuente"},{"id":"i3","texto":"Barras desde 19 con título \"subimos un 10 %\""},{"id":"i4","texto":"Barras desde 19 con título \"¡triplicamos!\""}],"extremos":["Más honesta","Más engañosa"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La honestidad está en el dibujo, en el título y en el contexto.","valores":{"i1":"honesta y con contexto","i2":"correcta pero incompleta","i3":"título honesto, dibujo exagerado","i4":"engañosa"}}},{"slug":"ciencia-2.s7.p8","orden":8,"grupo":"ciencia-2.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un medio publica su análisis del gráfico. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El reciclaje aumentó un 10 %, no se triplicó."},{"id":"s2","texto":"El eje recortado hace que la barra de 2024 parezca el triple de la de 2023."},{"id":"s3","texto":"El reciclaje subió 10 puntos porcentuales."},{"id":"s4","texto":"Como el reciclaje subió, el problema de la basura está resuelto."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Hasta un buen análisis puede confundir puntos con porcentajes. Revisar cada número es la tarea.","por_opcion":{"s3":"Subió un 10 % en toneladas; como porcentaje de los residuos, pasó de 5 % a 5,5 %: medio punto.","s4":"Se recicla el 5,5 %: el resto sigue yendo a disposición final."}}}]}]}$ac$::jsonb);
